"""Project saved original observations into ordinary Monitoring source context.

Read-only preview retains the original import and explicit qualifier meanings.
Preparation uses Workspace.import_sources and the existing observed-context store.
No flow, station, annual mass, concentration trend or native model is generated.
"""
from __future__ import annotations

import argparse
from collections import Counter
from copy import deepcopy
from datetime import date
import hashlib
import json
import math
from pathlib import Path
import re
import tempfile

from .common import identifier, relative_file, verify_file
from .monitoring_common import ContractError, canonical_bytes, digest, file_sha256
from . import monitoring_observed_context as observed

EDITION = "upstate.native-observation-monitoring-context/v1"
OPTIONAL_COLUMNS = (
    "activity", "fraction", "depth", "depth_unit", "method_authority", "value_type",
    "weight_basis", "time_basis", "temperature_basis", "particle_size_basis",
    "project", "time", "timezone", "reporting_limit", "reporting_limit_unit", "comment",
    "activity_type", "sample_media", "sample_media_subdivision", "method_name",
    "method_specification", "organization_id", "analytical_fraction",
    "result_depth", "result_depth_unit",
)
DEFAULT_INTERPRETATION = {
    "columns": {}, "below_qualifiers": ["<", "<="], "above_qualifiers": [">", ">="],
    "numeric_qualifiers": [""], "nonnegative": False, "use_limit_unit_when_missing": False,
}
SELECTION_KEYS = {"observation_id", "network_id", "plan_id", "campaign_id",
                  "station_mapping", "title", "interpretation"}
INLINE_LIMIT = re.compile(r"^\s*(<=|>=|<|>|≤|≥)\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*$")
FLOW_UNAVAILABLE = {
    "status": "not_received",
    "reason": "No daily-flow series was selected for this native observation context.",
}


def _text(value, label, *, empty=False):
    if not isinstance(value, str) or (not empty and not value.strip()):
        raise ContractError(label + " must be original text")
    return value


def _number(value, label):
    if isinstance(value, bool):
        raise ContractError(label + " must be finite")
    try:
        result = float(value)
    except (ValueError, TypeError, OverflowError) as error:
        raise ContractError(label + " must be finite") from error
    if not math.isfinite(result):
        raise ContractError(label + " must be finite")
    return result


def interpretation(value, columns):
    if not isinstance(value, dict) or set(value) - set(DEFAULT_INTERPRETATION):
        raise ContractError("Choose the explicit original-column and qualifier interpretation")
    result = deepcopy(DEFAULT_INTERPRETATION)
    result.update(deepcopy(value))
    if any(type(result[key]) is not bool for key in ("nonnegative", "use_limit_unit_when_missing")):
        raise ContractError("Nonnegative support and missing-unit choices must be explicit booleans")
    selected = result["columns"]
    if not isinstance(selected, dict) or set(selected) - set(OPTIONAL_COLUMNS):
        raise ContractError("Optional mapping contains an unsupported context field")
    if any(not isinstance(column, str) or (column and column not in columns) for column in selected.values()):
        raise ContractError("Optional mappings must select exact retained original column names")
    groups = []
    for key in ("below_qualifiers", "above_qualifiers", "numeric_qualifiers"):
        values = result[key]
        if not isinstance(values, list) or any(not isinstance(token, str) or token != token.strip() for token in values):
            raise ContractError("Qualifier meanings must list exact retained tokens without surrounding whitespace")
        if len(values) != len(set(values)):
            raise ContractError("A qualifier meaning repeats")
        result[key] = sorted(values)
        groups.append(set(values))
    if any(groups[a] & groups[b] for a in range(3) for b in range(a + 1, 3)):
        raise ContractError("Each qualifier must have only one explicit meaning")
    return result


def _native(workspace, observation_id):
    key = identifier(observation_id)
    value = workspace._get("observations", key)
    if (value.get("schema") != "upstate.observations/v1"
            or not isinstance(value.get("metadata"), dict)
            or not isinstance(value.get("rows"), list)
            or any(not isinstance(row, dict) for row in value["rows"])
            or not isinstance(value.get("columns"), list)
            or any(not isinstance(column, str) for column in value["columns"])
            or len(value["columns"]) != len(set(value["columns"]))):
        raise ContractError("The native observation record lacks its original rows, columns or metadata")
    original = value.get("original")
    if not isinstance(original, dict) or not original.get("object"):
        raise ContractError("The native observation record lacks its retained original file")
    verify_file(workspace.root, {**original, "path": original["object"]})
    record = relative_file(workspace.root, "observations/" + key + ".json")
    return value, record


def catalog(workspace):
    values = []
    for path in sorted((workspace.root / "observations").glob("*.json")):
        source, _ = _native(workspace, path.stem)
        metadata = source.get("metadata", {})
        rows = source["rows"]
        values.append({
            "observation_id": source["id"], "title": metadata.get("title", source["id"]),
            "rows": len(rows), "columns": deepcopy(source["columns"]),
            "stations": sorted({str(row.get("station_id", "")) for row in rows}),
            "qualifiers": sorted({str(row.get("qualifier") or "").strip() for row in rows}),
            "source_uri": metadata.get("source_uri"),
            "value_basis": metadata.get("value_basis"),
            "original_mapping": deepcopy(metadata.get("columns", {})),
            "interpretation": deepcopy(DEFAULT_INTERPRETATION),
            "optional_columns": list(OPTIONAL_COLUMNS),
        })
    return {"observations": values}


def _selection(workspace, selection, source):
    if not isinstance(selection, dict) or set(selection) - SELECTION_KEYS:
        raise ContractError("Select an original observation, native network and explicit interpretation")
    title = _text(selection.get("title"), "Context title").strip()
    mapping = selection.get("station_mapping", {})
    if not isinstance(mapping, dict) or any(not isinstance(k, str) or not k or
            not isinstance(v, str) or not v for k, v in mapping.items()):
        raise ContractError("Station mapping must use exact source and saved network IDs")
    network, plan, campaign = observed._selection(
        workspace, selection.get("network_id"), selection.get("plan_id"), selection.get("campaign_id"))
    source_ids = {str(row.get("station_id") or "") for row in source["rows"]}
    network_ids = {row["id"] for row in network["stations"]}
    if set(mapping) - source_ids or set(mapping.values()) - network_ids or len(set(mapping.values())) != len(mapping):
        raise ContractError("Explicit station mapping must select distinct existing native stations")
    result = {
        "observation_id": source["id"], "network_id": network["id"],
        "plan_id": plan["id"] if plan and not campaign else None,
        "campaign_id": campaign["revision"]["campaign_id"] if campaign else None,
        "station_mapping": deepcopy(mapping), "title": title,
        "interpretation": interpretation(selection.get("interpretation", {}), source["columns"]),
    }
    return result, network


def _optional(row, metadata, options, field):
    # A deliberately blank optional mapping disables a retained default.
    if field in options["columns"]:
        column = options["columns"][field]
        return (column != ""), row.get("original", {}).get(column) if column else None
    column = metadata.get("columns", {}).get(field)
    if column:
        return column in row.get("original", {}), row.get("original", {}).get(column)
    if field in row:
        return True, row[field]
    if field in metadata:
        return True, metadata[field]
    return False, None


def _day(value):
    if not isinstance(value, str) or date.fromisoformat(value).isoformat() != value:
        raise ValueError("Original date needs one complete ISO calendar day")
    return value


def _row(source, row, options):
    metadata = source.get("metadata", {})
    row_id = _text(row.get("id"), "Original row ID")
    raw = row.get("original")
    if not isinstance(raw, dict):
        raise ContractError("Each native row must retain its original cells")
    picked = {field: _optional(row, metadata, options, field) for field in OPTIONAL_COLUMNS}
    def text(field):
        present, value = picked[field]
        return str(value).strip() if present and value is not None else ""
    station = str(row.get("station_id") or "")
    activity = text("activity") or source["id"] + ":" + row_id
    result = {
        "observation_id": digest({"observation_id": source["id"], "original_record_id": row_id}),
        "original_observation_id": source["id"], "original_record_id": row_id,
        "source_row": row.get("line"), "source_file": deepcopy(source["original"]),
        "original_cells": deepcopy(raw), "original_record": deepcopy(row),
        "station_id": station, "activity_id": activity,
        "activity_identity_basis": "original_activity" if text("activity") else "original_record",
        "date": row.get("period_start"),
        "characteristic": row.get("original_parameter", row.get("parameter")),
        "method": row.get("method"), "unit": row.get("unit"), "original_unit": row.get("unit"),
        "qualifier": str(row.get("qualifier") or "").strip(),
        "result_text": str(row.get("value_text") or ""),
        "result_value": None, "limit_value": None, "lower": None, "upper": None,
        "lower_unbounded": False, "upper_unbounded": False,
        "status": "uninterpreted",
        "sampling_cohort_schema": "upstate.native-observation-sampling-cohort/v1",
        "time_support": row.get("time_support"), "quantity_basis": row.get("quantity_basis"),
        "measurement_support": row.get("measurement_support"),
    }
    # Preserve field presence, nulls and blank original values in cohort keys.
    names = {
        "fraction": ("fraction", "sample_fraction"),
        "depth": ("depth_value",), "depth_unit": ("depth_unit",),
        "method_authority": ("method_context",),
        "value_type": ("value_type", "result_value_type"),
        "project": ("project_id",), "time": ("time",), "timezone": ("timezone",),
        "comment": ("comment",), "result_depth": ("result_depth_value",),
        "result_depth_unit": ("result_depth_unit",),
    }
    for field, (present, value) in picked.items():
        if not present or field in ("activity", "reporting_limit", "reporting_limit_unit"):
            continue
        for key in names.get(field, (field,)):
            result[key] = deepcopy(value)
    if "species" in row:
        result["speciation"] = deepcopy(row["species"])
    if "method" in row:
        result["method_id"] = deepcopy(row["method"])
    reasons = []
    try:
        _day(result["date"])
        if row.get("period_end") and row["period_end"] != result["date"]:
            reasons.append("Multi-day original support is not a single-day observation")
    except (ValueError, TypeError):
        reasons.append("Original date needs one complete ISO calendar day")
    if metadata.get("value_basis") == "annual_mass_rate":
        reasons.append("Annual mass-rate records remain in their original native load comparison")
    qualifier = result["qualifier"]
    raw_value = result["result_text"].strip()
    inline = INLINE_LIMIT.fullmatch(raw_value)
    direction = ("below" if qualifier in options["below_qualifiers"] else
                 "above" if qualifier in options["above_qualifiers"] else
                 "numeric" if qualifier in options["numeric_qualifiers"] else None)
    if inline:
        inline_direction = "below" if inline[1] in ("<", "<=", "≤") else "above"
        if qualifier and direction != inline_direction:
            reasons.append("Inline limit and original qualifier have different or unreviewed meanings")
        direction = inline_direction
    limit_text, limit_unit = text("reporting_limit"), text("reporting_limit_unit")
    result["limit_unit"] = limit_unit if picked["reporting_limit_unit"][0] else result["unit"]
    if limit_text:
        try:
            result["limit_value"] = _number(limit_text, "Original reporting limit")
        except ValueError as error:
            reasons.append(str(error))
    try:
        if direction in ("below", "above"):
            limit = _number(limit_text or (inline[2] if inline else raw_value), "Original reporting limit")
            unit = result["unit"]
            if not unit and limit_unit and options["use_limit_unit_when_missing"]:
                result["unit"] = limit_unit
                result["unit_origin"] = "Original reporting-limit unit; explicit missing-unit choice"
            if limit_unit and limit_unit != result["unit"]:
                raise ContractError("Reporting-limit and measurement units differ; no conversion was selected")
            if options["nonnegative"] and limit < 0:
                raise ContractError("Negative limit conflicts with selected nonnegative support")
            result["limit_value"] = limit
            result["limit_unit"] = limit_unit or result["unit"]
            if direction == "below":
                result.update(lower=0.0 if options["nonnegative"] else None, upper=limit,
                              lower_unbounded=not options["nonnegative"], status="below_limit")
            else:
                result.update(lower=limit, upper=None, upper_unbounded=True, status="above_limit")
            # No "<" versus "<=" meaning is invented for a textual qualifier.
            if inline:
                result["limit_operator"] = inline[1]
        elif direction == "numeric" and not inline:
            number = _number(raw_value, "Original result")
            if options["nonnegative"] and number < 0:
                raise ContractError("Negative result conflicts with selected nonnegative support")
            result.update(result_value=number, lower=number, upper=number, status="measured")
        else:
            reasons.append("Original qualifier has no explicitly selected numeric or limit meaning: " + repr(qualifier))
    except (ValueError, TypeError) as error:
        reasons.append(str(error))
    if not station or not result["characteristic"] or not result["unit"]:
        reasons.append("Original station, characteristic and measurement unit are required")
    if reasons:
        result["reasons"] = list(dict.fromkeys(reasons))
    return result


def _stations(source, selected, network):
    originals = sorted({str(row.get("station_id") or "") for row in source["rows"] if row.get("station_id")})
    native = {row["id"]: row for row in network["stations"]}
    result = []
    for key in originals:
        target = selected["station_mapping"].get(key, key)
        retained = native.get(target)
        point = retained.get("geometry", {}) if retained else {}
        coords = point.get("coordinates") if point.get("type") == "Point" else None
        item = {"station_id": key, "station_name": key, "longitude": None, "latitude": None,
                "datum": None, "coordinate_origin": "not_received"}
        if coords and len(coords) >= 2:
            item.update(longitude=coords[0], latitude=coords[1], datum="WGS84",
                        coordinate_origin="retained_network_station",
                        coordinate_network_station_id=target,
                        coordinate_network_id=network["id"],
                        coordinate_source_bindings=deepcopy(network.get("source_bindings", {})))
        result.append(item)
    return result


def _document(workspace, source, record_path, selected, network):
    binding = {
        "observation_id": source["id"], "project_id": workspace.project["id"],
        "record_sha256": file_sha256(record_path), "original_file": deepcopy(source["original"]),
        "source_uri": source.get("metadata", {}).get("source_uri"),
        "title": source.get("metadata", {}).get("title", source["id"]),
        "original_mapping": deepcopy(source.get("metadata", {}).get("columns", {})),
        "original_options": deepcopy(source.get("metadata", {})),
        "selection": deepcopy(selected), "row_count": len(source["rows"]),
    }
    rows = [_row(source, row, selected["interpretation"]) for row in source["rows"]]
    if len({row["original_record_id"] for row in rows}) != len(rows):
        raise ContractError("Original native row IDs repeat")
    # An activity is one original station/date. Ambiguous original IDs remain excluded.
    activity_dates = {}
    for row in rows:
        if "reasons" not in row:
            activity_dates.setdefault((row["station_id"], row["activity_id"]), set()).add(row["date"])
    for row in rows:
        if len(activity_dates.get((row["station_id"], row["activity_id"]), set())) > 1:
            row.setdefault("reasons", []).append("Original activity ID refers to more than one date")
    included = [row for row in rows if "reasons" not in row]
    excluded = [row for row in rows if "reasons" in row]
    dates = []
    for row in rows:
        try:
            dates.append(_day(row["date"]))
        except (ValueError, TypeError):
            pass
    if not dates:
        raise ContractError("No original ISO observation date is available; inspect the original import mapping")
    activities = {}
    for row in included:
        key = (row["station_id"], row["activity_id"])
        item = {"station_id": row["station_id"], "activity_id": row["activity_id"], "date": row["date"],
                "activity_identity_basis": row["activity_identity_basis"]}
        if "activity_type" in row:
            item["activity_type"] = row["activity_type"]
        activities.setdefault(key, item)
    value = {
        "schema": observed.CONCENTRATION_SOURCE_SCHEMA, "title": selected["title"],
        "source_edition": digest({"edition": EDITION, "native": binding, "network": digest(network)}),
        "native_observation_binding": binding,
        "source_period": {"start_inclusive": min(dates), "end_inclusive": max(dates)},
        "flow_scope": {"mode": "unavailable", "station_ids": []},
        "flow_availability": deepcopy(FLOW_UNAVAILABLE),
        "stations": _stations(source, selected, network),
        "activities": list(activities.values()), "observations": included, "excluded_observations": excluded,
        "daily_flow": [], "relations": [], "annual_coverage": [], "station_year_coverage": [],
        "monthly_coverage": [], "high_flow_episodes": [], "paired_contrasts": [],
        "interpretation": [
            "Values are original source observations with explicit qualifier and unit choices; censored limits are not measured values.",
            "All original rows, raw cells, original import mapping and the exact original file remain retained; excluded rows carry their individual reasons.",
            "When no original activity identifier is selected, an explicit original_record identity groups that row only; it does not establish a separate field activity or visit.",
            "No daily-flow series was selected or inferred from these observation rows. Flow-linked episodes, event coverage, mass loads and modeled export comparisons are unavailable.",
            "Station assignment uses only an existing native network station with exact identifier or explicit mapping. Network geometry is labeled as such.",
            "Methods, fractions, depth, value type, units, project metadata and declared time/quantity/measurement support remain separate original Sampling cohorts; no unit conversion is performed.",
        ],
    }
    observed._validate(value)
    return value


def _cohorts(context):
    from .monitoring_recommendations import _cohort
    values = {}
    for row in context["observations"]:
        key, fields = _cohort(row)
        item = values.setdefault(key, {"id": key, "fields": fields, "observation_count": 0,
                                      "station_ids": set(), "original_record_ids": []})
        item["observation_count"] += 1
        item["station_ids"].add(row["station_id"])
        item["original_record_ids"].append(row["original_record_id"])
    return [{**item, "station_ids": sorted(item["station_ids"])} for _, item in sorted(values.items())]


def _preview(workspace, selection):
    if not isinstance(selection, dict):
        raise ContractError("The native observation selection must be an object")
    source, record_path = _native(workspace, selection.get("observation_id"))
    selected, network = _selection(workspace, selection, source)
    document = _document(workspace, source, record_path, selected, network)
    body = canonical_bytes(document)
    binding = {"source_id": None, "source_collection_id": None, "source_record_id": None,
               "title": selected["title"], "filename": "observed-context.json",
               "bytes": len(body), "object_sha256": hashlib.sha256(body).hexdigest()}
    context = observed._preview(workspace, value=document, binding=binding,
        network_id=selected["network_id"], plan_id=selected["plan_id"],
        campaign_id=selected["campaign_id"], station_mapping=selected["station_mapping"], title=selected["title"])
    identity = digest({"edition": EDITION, "selection": selected, "document": binding["object_sha256"],
                       "context": context})
    result = {"id": identity, "selection": selected, "source": document["native_observation_binding"],
              "context": context, "cohorts": _cohorts(context),
              "summary": {**context["summary"], "included_source_rows": len(document["observations"]),
                          "excluded_source_rows": len(document["excluded_observations"]),
                          "status_counts": dict(Counter(row["status"] for row in document["observations"]))}}
    return result, document, source, record_path


def preview(workspace, *, selection):
    return _preview(workspace, selection)[0]


def verify_binding(workspace, binding):
    if not isinstance(binding, dict):
        raise ContractError("Native observation provenance must be a retained object")
    identifier(binding.get("observation_id"))
    identifier(binding.get("record_sha256"))
    if binding.get("project_id") != workspace.project["id"]:
        return  # Foreign ordinary source remains complete in its original CAS companions.
    source, path = _native(workspace, binding["observation_id"])
    if (file_sha256(path) != binding["record_sha256"]
            or source["original"] != binding.get("original_file")
            or len(source["rows"]) != binding.get("row_count")
            or source.get("metadata", {}).get("columns", {}) != binding.get("original_mapping")
            or source.get("metadata", {}) != binding.get("original_options")):
        raise ContractError("The saved native observation binding differs from its original import")


def prepare(workspace, *, selection, expected_preview_id):
    result, document, source, record_path = _preview(workspace, selection)
    if identifier(expected_preview_id) != result["id"]:
        raise ContractError("The original observation, network or interpretation changed; preview the same selection again")
    source_id = "native-observations-" + result["id"]
    with tempfile.TemporaryDirectory(prefix="monitoring-native-context-") as directory:
        folder = Path(directory)
        (folder / "observed-context.json").write_bytes(canonical_bytes(document))
        original = relative_file(workspace.root, source["original"]["object"])
        # Byte-exact source files; neither the native importer nor its record is modified.
        (folder / "original.csv").write_bytes(original.read_bytes())
        (folder / "original-native-observation.json").write_bytes(record_path.read_bytes())
        (folder / "native-selection.json").write_bytes(canonical_bytes(result["selection"]))
        manifest = {"schema": "upstate.sources/v1", "title": result["selection"]["title"],
            "notes": document["interpretation"], "entries": [{
                "id": source_id, "title": result["selection"]["title"],
                "uri": "urn:upstate:native-observation-context:" + workspace.project["id"] + ":" + result["id"],
                "vintage": document["source_period"]["end_inclusive"],
                "kind": "document", "role": "monitoring_observed_context",
                "path": "observed-context.json", "sha256": result["context"]["source_binding"]["object_sha256"],
                "metadata": {"native_observation_id": source["id"], "context_schema": document["schema"],
                             "preview_id": result["id"], "flow_availability": "not_received"},
                "companions": [
                    {"path": "original.csv", "sha256": source["original"]["sha256"]},
                    {"path": "original-native-observation.json", "sha256": document["native_observation_binding"]["record_sha256"]},
                    {"path": "native-selection.json", "sha256": digest(result["selection"])},
                ],
            }]}
        (folder / "manifest.json").write_bytes(canonical_bytes(manifest))
        verify_binding(workspace, document["native_observation_binding"])
        collection = workspace.import_sources(folder / "manifest.json")
    selected = result["selection"]
    actual = observed.preview(workspace, source_collection_id=collection["id"], source_id=source_id,
        network_id=selected["network_id"], plan_id=selected["plan_id"], campaign_id=selected["campaign_id"],
        station_mapping=selected["station_mapping"], title=selected["title"])
    if ({k: v for k, v in actual.items() if k != "source_binding"}
            != {k: v for k, v in result["context"].items() if k != "source_binding"}):
        raise ContractError("Native context projection changed during source preparation")
    saved = workspace._save(observed.COLLECTION, actual)
    return observed.inspect(workspace, saved["id"])


def main():
    from .workspace import Workspace
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", required=True)
    commands = parser.add_subparsers(dest="command", required=True)
    commands.add_parser("catalog")
    for name in ("preview", "prepare"):
        command = commands.add_parser(name)
        command.add_argument("--selection", type=Path, required=True)
        if name == "prepare":
            command.add_argument("--expected-preview-id", required=True)
    args = parser.parse_args()
    workspace = Workspace(args.workspace)
    if args.command == "catalog":
        result = catalog(workspace)
    else:
        selection = json.loads(args.selection.read_text(encoding="utf-8"))
        result = (preview(workspace, selection=selection) if args.command == "preview" else
                  prepare(workspace, selection=selection, expected_preview_id=args.expected_preview_id))
    print(json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False))


if __name__ == "__main__":
    main()

"""Bind original monitoring observations to an existing network and saved calendar.

This is descriptive source context. It never modifies the network, solver,
planning costs, selected catchments, campaign revision or source observations.
"""
from __future__ import annotations
import argparse
import csv
import html
import io
import json
import math
from collections import defaultdict
from datetime import date
from pathlib import Path

from .monitoring_common import ContractError, canonical_bytes, digest, file_sha256, load_json
from .monitoring_sources import source_record, verify_binding, export_source

SOURCE_SCHEMA = "upstate.monitoring-observed-source/v1"
SCOPED_SOURCE_SCHEMA = "upstate.monitoring-observed-source/v2"
CONCENTRATION_SOURCE_SCHEMA = "upstate.monitoring-observed-source/v3"
SCHEMA = "upstate.monitoring_observed_contexts/v1"
COLLECTION = "monitoring_observed_contexts"


def _service(workspace):
    from .monitoring_workspace import MonitoringWorkspace
    return MonitoringWorkspace(workspace)


def _date(value):
    if not isinstance(value, str):
        raise ContractError("Observed and calendar dates must be original ISO date strings")
    try:
        parsed = date.fromisoformat(value)
    except ValueError as exc:
        raise ContractError("Invalid original date: " + value) from exc
    if parsed.isoformat() != value:
        raise ContractError("Observed dates must be YYYY-MM-DD")
    return value


def _id(value, label):
    if not isinstance(value, str) or not value.strip() or value != value.strip():
        raise ContractError(label + " must be an exact nonempty original identifier")
    return value


def _number(value, label):
    if isinstance(value, bool):
        raise ContractError(label + " must be numeric")
    try:
        number = float(value)
    except (ValueError, TypeError, OverflowError) as exc:
        raise ContractError(label + " must be finite") from exc
    if not math.isfinite(number):
        raise ContractError(label + " must be finite")
    return number


def _flow_scope(value):
    """Return the declared station-specific flow selection without broadening it."""
    scope = value.get("flow_scope")
    if scope is None:
        return None
    if isinstance(scope, dict) and scope.get("mode") == "unavailable":
        if value.get("schema") != CONCENTRATION_SOURCE_SCHEMA or scope != {"mode": "unavailable", "station_ids": []}:
            raise ContractError("Unavailable flow requires the explicit concentration-only source schema")
        return scope
    if not isinstance(scope, dict) or scope.get("mode") != "same_station_only":
        raise ContractError("Observed flow scope must declare same_station_only")
    gauge = _id(scope.get("gauge_station_id"), "flow gauge station")
    stations = scope.get("station_ids")
    if not isinstance(stations, list) or stations != [gauge]:
        raise ContractError("Same-station flow scope must select only its original gauge station")
    start, end = scope.get("start_inclusive"), scope.get("end_inclusive")
    if (start is None) != (end is None):
        raise ContractError("Flow scope must retain both original period endpoints")
    if start is not None and _date(end) < _date(start):
        raise ContractError("Original flow scope period is reversed")
    return scope


def _flow_applies(scope, station, day):
    if scope is None:
        return True
    if scope.get("mode") == "unavailable":
        return False
    return (station in scope["station_ids"] and
            (scope.get("start_inclusive") is None or
             scope["start_inclusive"] <= day <= scope["end_inclusive"]))


def _episode_activity(scope, row):
    return (_flow_applies(scope, row["station_id"], row["date"]) and
            (scope is None or row.get("activity_type") == "Sample-Routine"))


def _validate(value):
    if not isinstance(value, dict) or value.get("schema") not in {SOURCE_SCHEMA, SCOPED_SOURCE_SCHEMA, CONCENTRATION_SOURCE_SCHEMA}:
        raise ContractError("Select an original monitoring observational context source")
    needed = ("stations", "activities", "daily_flow", "relations", "annual_coverage",
              "station_year_coverage", "monthly_coverage", "high_flow_episodes", "paired_contrasts")
    if any(not isinstance(value.get(key), list) for key in needed):
        raise ContractError("The retained context lacks its complete source tables")
    stations = {}
    for row in value["stations"]:
        station = _id(row["station_id"], "source station")
        if station in stations:
            raise ContractError("Original station IDs repeat")
        if value["schema"] == CONCENTRATION_SOURCE_SCHEMA and row.get("coordinate_origin") == "not_received":
            if any(row.get(key) is not None for key in ("longitude", "latitude", "datum")):
                raise ContractError("Missing station coordinates must remain explicitly unavailable")
            stations[station] = row
            continue
        lon = _number(row["longitude"], "station longitude")
        lat = _number(row["latitude"], "station latitude")
        if (not -180 <= lon <= 180 or not -90 <= lat <= 90
                or row.get("datum") not in {"WGS84", "NAD83"}):
            raise ContractError("Original geographic station coordinates require their declared WGS84 or NAD83 datum")
        stations[station] = row
    if value["schema"] == SCOPED_SOURCE_SCHEMA and value.get("flow_scope") is None:
        raise ContractError("A v2 observed source requires its explicit original station flow scope")
    _flow_scope(value)
    if value["schema"] == CONCENTRATION_SOURCE_SCHEMA:
        if (value.get("flow_scope") != {"mode": "unavailable", "station_ids": []}
                or not isinstance(value.get("flow_availability"), dict)
                or value["flow_availability"].get("status") != "not_received"):
            raise ContractError("Concentration-only context must explicitly retain unavailable daily flow")
        if any(value[key] for key in ("daily_flow", "high_flow_episodes", "paired_contrasts")):
            raise ContractError("A concentration-only source cannot claim flow-derived support")
        if not isinstance(value.get("native_observation_binding"), dict):
            raise ContractError("Concentration-only source requires its original native observation binding")
        if not isinstance(value.get("excluded_observations", []), list):
            raise ContractError("Excluded original observations must remain a complete source table")
    seen = set()
    activity_dates = {}
    for row in value["activities"]:
        station = row["station_id"]
        identity = (station, _id(row["activity_id"], "source activity"))
        if station not in stations or identity in seen:
            raise ContractError("Source activity is ambiguous or belongs to an unknown station")
        seen.add(identity)
        activity_dates[identity] = _date(row["date"])
    observations = value.get("observations", [])
    if not isinstance(observations, list):
        raise ContractError("Original observations must be a complete source table")
    observed_ids = set()
    for row in observations:
        if not isinstance(row, dict):
            raise ContractError("Each original observation must be a source record")
        identity = _id(row.get("observation_id"), "original observation")
        station = _id(row.get("station_id"), "observation station")
        activity = _id(row.get("activity_id"), "observation activity")
        if identity in observed_ids or activity_dates.get((station, activity)) != _date(row.get("date")):
            raise ContractError("Original observation repeats or differs from its station/activity/date")
        observed_ids.add(identity)
        for field in ("result_value", "limit_value", "lower", "upper"):
            if row.get(field) is not None:
                _number(row[field], "observation " + field)
        if row.get("upper_unbounded") is True and row.get("upper") is not None:
            raise ContractError("An unbounded original upper interval must retain a null upper value")
        if (row.get("lower") is not None and row.get("upper") is not None
                and float(row["lower"]) > float(row["upper"])):
            raise ContractError("Original observation interval is reversed")
    start = _date(value["source_period"]["start_inclusive"])
    end = _date(value["source_period"]["end_inclusive"])
    if end < start:
        raise ContractError("Source period is reversed")
    days = {}
    for row in value["daily_flow"]:
        day = _date(row["date"])
        if day in days or not start <= day <= end:
            raise ContractError("Original daily flow date repeats or exceeds its stated period")
        flow = _number(row["mean_cfs"], "source daily mean")
        threshold = _number(row["p95_cfs"], "source annual P95")
        if flow < 0 or threshold < 0 or type(row["at_or_above_annual_p95"]) is not bool:
            raise ContractError("Daily flow threshold fields are invalid")
        if row["at_or_above_annual_p95"] != (flow >= threshold):
            raise ContractError("Source daily threshold flag differs from its retained values")
        days[day] = row
    if not stations or (not days and value["schema"] != CONCENTRATION_SOURCE_SCHEMA):
        raise ContractError("Original stations and daily support are required")
    episodes = set()
    for row in value["high_flow_episodes"]:
        key = _id(row["event_id"], "original episode")
        if key in episodes or _date(row["end_date"]) < _date(row["start_date"]):
            raise ContractError("Source high-flow episodes repeat or have reversed dates")
        episodes.add(key)
    return value


def _source(workspace, collection_id, source_id, *, include_value=True):
    from .common import relative_file
    collection = workspace._get("sources", collection_id)
    entries = [entry for entry in collection["entries"] if entry["id"] == source_id]
    if len(entries) != 1:
        raise ContractError("Original observational source entry is absent or ambiguous")
    entry = entries[0]
    for member in [entry["body"], *entry.get("companions", []), collection["original_manifest"]]:
        original = relative_file(workspace.root, member["object"])
        if original.stat().st_size != member["bytes"] or file_sha256(original) != member["sha256"]:
            raise ContractError("Original observational source or companion changed")
    path = relative_file(workspace.root, entry["body"]["object"])
    if entry.get("kind") != "document" or entry.get("role") != "monitoring_observed_context":
        raise ContractError("Select the registered monitoring observational document")
    expected = entry.get("body", {})
    actual = file_sha256(path)
    if expected.get("sha256") != actual or expected.get("bytes") != path.stat().st_size:
        raise ContractError("The original observational source body changed")
    # Intake validates the complete original document. A saved context is bound
    # to these exact bytes, so inspection need not materialize it again.
    value = _validate(load_json(path)) if include_value else None
    binding = {
        "source_id": source_id, "source_collection_id": collection_id,
        "source_record_id": collection["id"], "title": entry.get("title", ""),
        "filename": path.name, "bytes": path.stat().st_size, "object_sha256": actual,
    }
    return value, binding


def catalog(workspace):
    sources = []
    for collection in workspace.sources():
        for entry in collection.get("entries", []):
            if entry.get("kind") == "document" and entry.get("role") == "monitoring_observed_context":
                value, binding = _source(workspace, collection["id"], entry["id"])
                sources.append({**binding, "source_schema": value["schema"], "period": value["source_period"],
                                "stations": [{"station_id": row["station_id"],
                                              "station_name": row.get("station_name", row["station_id"]),
                                              "datum": row["datum"]}
                                             for row in value["stations"]],
                                "activities": len(value["activities"]),
                                "observations": len(value.get("observations", [])),
                                "flow_scope": value.get("flow_scope"),
                                "gauge_days": len(value["daily_flow"])})
    return {"sources": sources}


def _distance(a, b):
    lon1, lat1 = map(math.radians, a)
    lon2, lat2 = map(math.radians, b)
    term = math.sin((lat2 - lat1) / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin((lon2 - lon1) / 2) ** 2
    return 6371008.8 * 2 * math.asin(min(1.0, math.sqrt(term)))


def _selection(workspace, network_id, plan_id, campaign_id):
    service = _service(workspace)
    if plan_id and campaign_id:
        raise ContractError("Choose a saved plan or campaign, not both")
    campaign = service.campaign(campaign_id) if campaign_id else None
    plan = campaign["plan"] if campaign else service.get("plans", plan_id) if plan_id else None
    if plan:
        if network_id and network_id != plan["network_id"]:
            raise ContractError("Selected plan belongs to a different monitoring network")
        network_id = plan["network_id"]
    if not network_id:
        raise ContractError("Choose the original saved monitoring network")
    network = service.get("networks", network_id)
    service.verify_sources(network)
    return network, plan, campaign


def preview(workspace, *, source_collection_id, source_id, network_id=None,
            plan_id=None, campaign_id=None, station_mapping=None,
            title="Observed support for the monitoring network"):
    value, binding = _source(workspace, source_collection_id, source_id)
    return _preview(workspace, value=value, binding=binding, network_id=network_id,
                    plan_id=plan_id, campaign_id=campaign_id,
                    station_mapping=station_mapping, title=title)


def _preview(workspace, *, value, binding, network_id=None, plan_id=None,
             campaign_id=None, station_mapping=None, title="Observed support for the monitoring network"):
    """Project a validated retained source; also used by read-only native intake."""
    network, plan, campaign = _selection(workspace, network_id, plan_id, campaign_id)
    mapping = station_mapping or {}
    if not isinstance(mapping, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in mapping.items()):
        raise ContractError("Station mapping must name exact original source IDs and saved network station IDs")
    source_stations = {s["station_id"]: s for s in value["stations"]}
    native_stations = {s["id"]: s for s in network["stations"]}
    if set(mapping) - set(source_stations) or set(mapping.values()) - set(native_stations):
        raise ContractError("Station mapping contains an unknown original or saved station ID")
    if len(set(mapping.values())) != len(mapping):
        raise ContractError("Explicit source stations must map to distinct native stations")
    flow_scope = _flow_scope(value)
    flow_unavailable = bool(flow_scope and flow_scope.get("mode") == "unavailable")
    by_station = defaultdict(list)
    by_station_day = defaultdict(list)
    observations_by_station = defaultdict(list)
    for row in value.get("observations", []):
        observations_by_station[row["station_id"]].append(row)
    for row in value["activities"]:
        by_station[row["station_id"]].append(row)
        by_station_day[(row["station_id"], row["date"])].append(row)
    matches = []
    resolved = {}
    selected_ids = set(plan["selected_ids"]) if plan else set()
    for key, original in source_stations.items():
        target = mapping.get(key, key if key in native_stations else None)
        native = native_stations.get(target)
        if native and target in resolved:
            raise ContractError("Two source stations would map to the same saved station")
        if native:
            resolved[target] = key
        point = native.get("geometry", {}) if native else {}
        coords = point.get("coordinates") if point.get("type") == "Point" else None
        distance = (_distance([original["longitude"], original["latitude"]], coords[:2])
                    if coords and original["datum"] == "WGS84"
                    and original.get("coordinate_origin") != "retained_network_station" else None)
        records = by_station[key]
        matches.append({
            "source_station_id": key, "source_station_name": original.get("station_name", key),
            "network_station_id": target, "match": "explicit_mapping" if key in mapping else "exact_station_id" if native else "absent_from_network",
            "catchment_id": native.get("huc_id") if native else None,
            "catchment_assignment": native.get("assignment") if native else None,
            "selected_search_area": bool(native and native.get("huc_id") in selected_ids),
            "coordinate_difference_m": distance,
            "coordinate_review": ("network_station_binding" if original.get("coordinate_origin") == "retained_network_station" else
                                  "unavailable" if original.get("coordinate_origin") == "not_received" else
                                  "different_datum" if original["datum"] != "WGS84" else
                                  "over_100m" if distance is not None and distance > 100 else
                                  "within_100m" if distance is not None else "unavailable"),
            "original_datum": original["datum"],
            "flow_scope_eligible": flow_scope is None or key in flow_scope["station_ids"],
            "observations": len(observations_by_station[key]),
            "activities": len(records), "sampling_dates": len({r["date"] for r in records}),
            "first_date": min((r["date"] for r in records), default=None),
            "last_date": max((r["date"] for r in records), default=None),
            "gauge_network_relation": original.get("gauge_network_relation"),
            "original_longitude": original["longitude"], "original_latitude": original["latitude"],
            "native_geometry": point if native else None,
        })
    if value["schema"] == CONCENTRATION_SOURCE_SCHEMA:
        for item in matches:
            source_station = source_stations[item["source_station_id"]]
            item["coordinate_origin"] = source_station.get("coordinate_origin")
            item["coordinate_source_bindings"] = source_station.get("coordinate_source_bindings")
    available = {m["source_station_id"] for m in matches if m["network_station_id"]}
    episode_scope_available = (available if flow_scope is None else
                               available.intersection(flow_scope["station_ids"]))
    days = {r["date"]: r for r in value["daily_flow"]}
    visits = campaign["calendar"] if campaign else plan["calendar"]["visits"] if plan and "calendar" in plan else []
    binding_map = campaign["revision"]["site_bindings"] if campaign else {}
    calendar = []
    for visit in visits:
        day = _date(visit["date"])
        native_id = binding_map.get(visit["site_id"])
        source_station = resolved.get(native_id)
        exact = by_station_day.get((source_station, day), []) if source_station else []
        flow_applicable = _flow_applies(flow_scope, source_station, day)
        flow = days.get(day) if flow_applicable else None
        if flow_unavailable:
            flow_status = "not_received"
        elif flow_scope is not None and source_station is None:
            flow_status = "station_not_bound_to_source"
        elif flow_scope is not None and source_station not in flow_scope["station_ids"]:
            flow_status = "station_outside_flow_scope"
        elif not flow_applicable:
            flow_status = "date_outside_flow_scope"
        else:
            flow_status = "received_original_date" if flow else "outside_received_daily_series"
        possible = [m["source_station_id"] for m in matches if m["catchment_id"] == visit["site_id"] and m["network_station_id"]]
        calendar.append({
            "visit_key": visit["visit_key"], "site_id": visit["site_id"], "date": day,
            "start_local": visit.get("start_local"), "finish_local": visit.get("finish_local"),
            "planned_network_station_id": native_id, "source_station_id": source_station,
            "station_basis": "retained_campaign_binding" if native_id else "unbound_search_area",
            "source_candidates_in_search_area": possible,
            "source_activity_ids_same_date": [r["activity_id"] for r in exact],
            "source_observation_status": "same_station_same_date" if exact else "no_same_station_sample" if source_station else "station_not_bound_to_source",
            "original_flow_status": flow_status,
            "flow_scope_applicable": flow_applicable,
            "flow_gauge_station_id": flow_scope.get("gauge_station_id") if flow_scope else None,
            "mean_cfs": flow["mean_cfs"] if flow else None,
            "flow_qualifiers": flow.get("qualifiers") if flow else None,
            "at_or_above_annual_p95": flow["at_or_above_annual_p95"] if flow else None,
            "source_daily_record": flow if flow else None,
            "planned_status": visit.get("status", "planned"),
        })
    episode_rows = []
    for episode in value["high_flow_episodes"]:
        overlap = [v for v in calendar if v["flow_scope_applicable"]
                   and episode["start_date"] <= v["date"] <= episode["end_date"]]
        actual = [r for r in value["activities"] if r["station_id"] in available
                  and _episode_activity(flow_scope, r)
                  and episode["start_date"] <= r["date"] <= episode["end_date"]]
        episode_rows.append({
            **episode, "matching_network_station_activities": len(actual),
            "matching_flow_scope_station_ids": sorted(episode_scope_available),
            "matching_network_station_ids": sorted({r["station_id"] for r in actual}),
            "matching_network_activity_ids": [r["activity_id"] for r in actual],
            "saved_calendar_visit_keys": [v["visit_key"] for v in overlap],
            "saved_calendar_bound_station_visit_keys": [v["visit_key"] for v in overlap if v["source_station_id"]],
        })
    selected_relations = [r for r in value["relations"]
                          if r["station_a"] in available and r["station_b"] in available]
    paired = [{**row, "both_stations_in_saved_network": row["station_a_id"] in available and row["station_b_id"] in available}
              for row in value["paired_contrasts"]]
    result = {
        "schema": SCHEMA, "title": str(title), "status": "retained_source_context",
        "source_binding": binding, "source_schema": value["schema"], "source_edition": value.get("source_edition"),
        "source_period": value["source_period"], "network_id": network["id"],
        "network_digest": digest(network), "plan_id": plan["id"] if plan else None,
        "plan_digest": digest(plan) if plan else None,
        "campaign_id": campaign["revision"]["campaign_id"] if campaign else None,
        "campaign_revision_id": campaign["revision"]["id"] if campaign else None,
        "campaign_revision_digest": digest(campaign["revision"]) if campaign else None,
        "campaign_snapshot": campaign["revision"] if campaign else None,
        "station_mapping": mapping, "station_matches": matches,
        "flow_scope": flow_scope,
        "observations": [row for row in value.get("observations", [])
                         if value["schema"] == CONCENTRATION_SOURCE_SCHEMA or row["station_id"] in available],
        "network_stations_without_source": sorted(set(native_stations) - set(resolved)),
        "calendar": calendar, "high_flow_episodes": episode_rows,
        "annual_coverage": value["annual_coverage"],
        "station_year_coverage": value["station_year_coverage"],
        "monthly_coverage": value["monthly_coverage"],
        "topology": value["relations"], "matched_topology": selected_relations,
        "paired_contrasts": paired,
        "summary": {
            "source_stations": len(source_stations), "matched_stations": len(available),
            "network_stations": len(native_stations), "source_activities": len(value["activities"]),
            "matched_station_activities": sum(len(by_station[key]) for key in available),
            "source_observations": len(value.get("observations", [])),
            "matched_station_observations": sum(len(observations_by_station[key]) for key in available),
            "matched_flow_scope_stations": sum(flow_scope is None or key in flow_scope["station_ids"]
                                               for key in available),
            "source_gauge_days": len(days), "source_high_flow_episodes": None if flow_unavailable else len(episode_rows),
            "source_unsampled_episodes": None if flow_unavailable else sum(r["sampled_dates"] == 0 for r in episode_rows),
            "matched_stations_unsampled_episodes": sum(r["matching_network_station_activities"] == 0 for r in episode_rows) if episode_scope_available else None,
            "saved_calendar_visits": len(calendar),
            "visits_with_received_daily_flow": sum(r["source_daily_record"] is not None for r in calendar),
            "visits_outside_received_daily_series": sum(r["original_flow_status"] == "outside_received_daily_series" for r in calendar),
            "visits_outside_flow_station_scope": sum(r["original_flow_status"] == "station_outside_flow_scope" for r in calendar),
            "visits_outside_flow_date_scope": sum(r["original_flow_status"] == "date_outside_flow_scope" for r in calendar),
            "visits_without_flow_station_binding": sum(r["original_flow_status"] == "station_not_bound_to_source" for r in calendar),
            "bound_source_station_visits": sum(r["source_station_id"] is not None for r in calendar),
            "visits_sharing_original_sample_station_date": sum(bool(r["source_activity_ids_same_date"]) for r in calendar),
            "high_flow_episodes_with_saved_calendar_date": None if flow_unavailable else sum(bool(r["saved_calendar_visit_keys"]) for r in episode_rows),
            "paired_contrasts_with_both_stations": sum(r["both_stations_in_saved_network"] for r in paired),
        },
        "interpretation": value["interpretation"] + [
            "Station matching uses exact original identifiers or an explicit retained mapping; activity identifiers are never used as stations.",
            "Saved-calendar overlap uses its unchanged absolute dates. It does not replay future dates into earlier years.",
            "An episode containing a planned visit has calendar overlap only. Existing collected field-event history remains in its original campaign.",
            "Source-year and month coverage includes the original full " + str(len(source_stations)) + "-station cohort. Matched-station counts are separately labeled.",
            "Original station datums are retained. NAD83 coordinates are not relabeled or transformed to WGS84; their point-distance comparison is marked different_datum.",
            "Matched observations retain their original values, censoring intervals, statuses, units, comments and source row identities.",
            ("No daily-flow series was received for this concentration context. Flow-linked episodes, event coverage and loads are unavailable."
             if flow_unavailable else "Daily flow and episode activity/calendar support apply only to the original gauge station " + flow_scope["gauge_station_id"] + ". Episode sampling counts include original Sample-Routine activities only."
             if flow_scope else "This unscoped source retains its original regional daily-flow date-context behavior."),
        ],
    }
    if value["schema"] == CONCENTRATION_SOURCE_SCHEMA:
        from copy import deepcopy
        for key in ("native_observation_binding", "flow_availability", "excluded_observations"):
            result[key] = deepcopy(value.get(key))
        result["summary"]["excluded_original_observations"] = len(value.get("excluded_observations", []))
        result["summary"]["source_original_rows"] = value["native_observation_binding"]["row_count"]
    return result


def prepare(workspace, **selection):
    result = preview(workspace, **selection)
    return workspace._save(COLLECTION, result)


def inspect(workspace, context_id):
    record = workspace._get(COLLECTION, context_id)
    if record.get("schema") != SCHEMA:
        raise ContractError("Saved monitoring context has an unsupported schema")
    _, retained_binding = _source(workspace, record["source_binding"]["source_collection_id"],
                                  record["source_binding"]["source_id"], include_value=False)
    if retained_binding != record["source_binding"]:
        raise ContractError("Saved monitoring context differs from its original source binding")
    service = _service(workspace)
    network = service.get("networks", record["network_id"])
    from .monitoring_sources import verify_retained_binding
    for binding in network["source_bindings"].values():
        if binding:
            verify_retained_binding(workspace, binding)
    if digest(network) != record["network_digest"]:
        raise ContractError("The retained monitoring network differs")
    if record.get("plan_id"):
        plan = service.get("plans", record["plan_id"])
        if digest(plan) != record["plan_digest"] or plan["network_id"] != network["id"]:
            raise ContractError("The retained monitoring plan differs")
    if record.get("campaign_revision_id"):
        revision = service.get("revisions", record["campaign_revision_id"])
        if digest(revision) != record["campaign_revision_digest"] or revision != record["campaign_snapshot"]:
            raise ContractError("The retained campaign revision differs")
        if revision["plan_id"] != record["plan_id"] or revision["network_id"] != record["network_id"]:
            raise ContractError("Saved campaign context points to a different plan")
    if record.get("native_observation_binding"):
        from .monitoring_native_observations import verify_binding as verify_native_binding
        verify_native_binding(workspace, record["native_observation_binding"])
    return record


def list_saved(workspace):
    rows = []
    for path in sorted((workspace.root / COLLECTION).glob("*.json")):
        row = workspace._get(COLLECTION, path.stem)
        if row.get("schema") != SCHEMA:
            raise ContractError("Saved monitoring context has an unsupported schema")
        rows.append({key: row.get(key) for key in ("id", "title", "network_id", "plan_id", "campaign_id",
                                                  "campaign_revision_id", "source_period", "summary")})
    return {"records": rows}


def _csv(rows):
    from .monitoring_workspace import csv_text
    fields = list(dict.fromkeys(key for row in rows for key in row))
    return csv_text(rows, fields).encode("utf-8")


def report_html(record):
    if record.get("source_schema") == CONCENTRATION_SOURCE_SCHEMA:
        from .monitoring_concentration_report import render
        return render(record)
    esc = lambda value: html.escape(str(value if value is not None else ""))
    def table(rows, fields):
        return "<div class='table'><table><thead><tr>" + "".join("<th>"+esc(k.replace("_", " "))+"</th>" for k in fields) + "</tr></thead><tbody>" + "".join("<tr>" + "".join("<td>"+esc(json.dumps(r.get(k), ensure_ascii=False) if isinstance(r.get(k), (dict, list)) else r.get(k))+"</td>" for k in fields) + "</tr>" for r in rows) + "</tbody></table></div>"
    summary = table([record["summary"]], list(record["summary"]))
    station_fields = ["source_station_id", "network_station_id", "match", "catchment_id",
                      "selected_search_area", "coordinate_difference_m", "coordinate_review",
                      "activities", "sampling_dates", "gauge_network_relation"]
    if "observations" in record:
        station_fields.insert(station_fields.index("coordinate_difference_m"), "original_datum")
        station_fields.insert(station_fields.index("sampling_dates"), "observations")
    stations = table(record["station_matches"], station_fields)
    calendar = table(record["calendar"], ["visit_key", "date", "planned_network_station_id", "source_station_id", "station_basis", "original_flow_status", "mean_cfs", "flow_qualifiers", "at_or_above_annual_p95", "source_activity_ids_same_date"])
    episodes = table(record["high_flow_episodes"], ["event_id", "start_date", "end_date", "peak_cfs", "sampled_dates", "matching_network_station_activities", "saved_calendar_visit_keys"])
    pairs = table(record["paired_contrasts"], ["date", "analyte", "upstream_station_id", "downstream_station_id", "contrast_unit", "downstream_direction", "downstream_minus_upstream_lower", "downstream_minus_upstream_upper", "downstream_difference_lower_open", "downstream_difference_upper_open", "clock_separation_minutes", "both_stations_in_saved_network"])
    topology = table(record["topology"], ["station_a", "station_b", "relation", "relation_basis", "path"])
    observations = table(record.get("observations", []), ["observation_id", "station_id", "activity_id", "date", "activity_type", "characteristic", "status", "result_value", "limit_value", "lower", "upper", "upper_unbounded", "unit", "method", "source_comment_flags", "source_result_comment", "source_file", "source_row"])
    observations_section = ("<h2>Original matched-station observations</h2>" + observations
                            if "observations" in record else "")
    notes = "<ul>" + "".join("<li>"+esc(v)+"</li>" for v in record["interpretation"]) + "</ul>"
    return ("<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
            "<title>"+esc(record["title"])+"</title><style>body{font:15px/1.5 system-ui,sans-serif;color:#171717;max-width:1200px;margin:32px auto;padding:0 18px}h1,h2{line-height:1.2}.table{overflow:auto;margin:14px 0}table{border-collapse:collapse;font-size:13px}th,td{border:1px solid #ccc;padding:7px;text-align:left;vertical-align:top}th{background:#eee}pre{white-space:pre-wrap;overflow-wrap:anywhere}a{color:inherit}@media print{body{max-width:none;margin:0}.table{overflow:visible}table{font-size:8px}tr{break-inside:avoid}}</style>"
            "<h1>"+esc(record["title"])+"</h1><p>Original observational context for a retained monitoring network and saved calendar.</p>"
            "<p>Period "+esc(record["source_period"]["start_inclusive"])+" to "+esc(record["source_period"]["end_inclusive"])+". Network "+esc(record["network_id"])+". Plan "+esc(record.get("plan_id"))+". Campaign revision "+esc(record.get("campaign_revision_id"))+".</p>"
            "<h2>Interpretation</h2>"+notes+"<h2>Coverage summary</h2>"+summary+"<h2>Original station matches</h2>"+stations+
            "<h2>Source network relations</h2>"+topology+"<h2>Exact saved calendar dates</h2>"+calendar+
            "<h2>Original high-flow episodes</h2>"+episodes+observations_section+"<h2>Same-date concentration intervals in downstream order</h2>"+pairs+
            "<h2>Complete source and selection</h2><pre>"+esc(json.dumps({k: record[k] for k in ("source_binding", "source_schema", "source_edition", "station_mapping", "flow_scope") if k in record}, indent=2, ensure_ascii=False))+"</pre></html>")



def _export_members(workspace, record):
    """Describe an already inspected context and its exact original source."""
    from .monitoring_packet import bytes_member
    from .monitoring_sources import source_export_members
    yield "observed-context/context.json", bytes_member(canonical_bytes(record))
    yield "observed-context/report.html", bytes_member(report_html(record).encode("utf-8"))
    for key in ("station_matches", "calendar", "high_flow_episodes", "annual_coverage",
                "station_year_coverage", "monthly_coverage", "topology", "paired_contrasts"):
        yield "observed-context/" + key.replace("_", "-") + ".csv", bytes_member(_csv(record[key]))
    if "observations" in record:
        yield "observed-context/observations.csv", bytes_member(_csv(record.get("observations", [])))
    if record.get("source_schema") == CONCENTRATION_SOURCE_SCHEMA:
        from .monitoring_concentration_report import export_tables
        for name, data in export_tables(record).items():
            yield name, bytes_member(data)
    yield from source_export_members(workspace, "monitoring-observations", record["source_binding"])


def export_members(workspace, context_id, *, plan_id=None, network_id=None):
    """Streamable descriptors with the same names and bytes as export_files."""
    record = inspect(workspace, context_id)
    if plan_id and record.get("plan_id") != plan_id:
        raise ContractError("Selected observational context belongs to another saved plan")
    if network_id and record["network_id"] != network_id:
        raise ContractError("Selected observational context belongs to another saved network")
    yield from _export_members(workspace, record)


def export_files(workspace, context_id, *, plan_id=None, network_id=None):
    record = inspect(workspace, context_id)
    if plan_id and record.get("plan_id") != plan_id:
        raise ContractError("Selected observational context belongs to another saved plan")
    if network_id and record["network_id"] != network_id:
        raise ContractError("Selected observational context belongs to another saved network")
    files = {"observed-context/context.json": canonical_bytes(record),
             "observed-context/report.html": report_html(record).encode("utf-8")}
    for key in ("station_matches", "calendar", "high_flow_episodes", "annual_coverage",
                "station_year_coverage", "monthly_coverage", "topology", "paired_contrasts"):
        files["observed-context/" + key.replace("_", "-") + ".csv"] = _csv(record[key])
    if "observations" in record:
        files["observed-context/observations.csv"] = _csv(record.get("observations", []))
    if record.get("source_schema") == CONCENTRATION_SOURCE_SCHEMA:
        from .monitoring_concentration_report import export_tables
        for name, data in export_tables(record).items():
            files[name] = data
    originals = export_source(workspace, "monitoring-observations", record["source_binding"])
    files.update(originals)
    return files



def export_context(workspace, *, context_id, export_root=None):
    """Stream the complete retained source context through original file tickets."""
    import uuid
    from .monitoring_packet import add_member, bytes_member, retain_packet
    service = _service(workspace)
    if export_root is not None:
        service.export_root = Path(export_root).resolve()
    record = inspect(workspace, context_id)
    files = {}
    for name, member in _export_members(workspace, record):
        add_member(files, name, member)
    add_member(files, "manifest.json", bytes_member(canonical_bytes({
        "schema": "upstate.monitoring-context-export/v1", "context_id": record["id"],
        "files": [{"path": name, "bytes": member["bytes"], "sha256": member["sha256"]}
                  for name, member in sorted(files.items())]})))
    base = service.export_root or workspace.root.parent / (workspace.root.name + "-monitoring-exports")
    folder = base / ("monitoring-context-" + uuid.uuid4().hex)
    folder.mkdir(parents=True, exist_ok=False)
    path = folder / "monitoring-observed-context.zip"
    retain_packet(path, files, metadata="export")
    return service._download(path, {"format": "observed-context", "context_id": record["id"],
                                    "network_id": record["network_id"], "plan_id": record["plan_id"],
                                    "files": len(files)})


def verify_workspace(workspace):
    ids = [path.stem for path in sorted((workspace.root / COLLECTION).glob("*.json"))]
    for identity in ids:
        inspect(workspace, identity)
    return {"observational_contexts": len(ids)}


def main():
    from .workspace import Workspace
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", required=True)
    commands = parser.add_subparsers(dest="command", required=True)
    commands.add_parser("catalog")
    for name in ("preview", "prepare"):
        command = commands.add_parser(name)
        command.add_argument("--selection", type=Path, required=True)
        command.add_argument("--output", type=Path, required=True)
    command = commands.add_parser("inspect")
    command.add_argument("--id", required=True)
    args = parser.parse_args()
    workspace = Workspace(args.workspace)
    if args.command == "catalog":
        result = catalog(workspace)
    elif args.command == "inspect":
        result = inspect(workspace, args.id)
    else:
        result = (preview if args.command == "preview" else prepare)(workspace, **load_json(args.selection))
        from .monitoring_common import atomic_json
        atomic_json(args.output, result)
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

"""One monitoring command surface used by the original queued operator and CLI."""
from __future__ import annotations
import inspect
from .monitoring_common import ContractError
from .monitoring_workspace import MonitoringWorkspace

READS = {"context.native.catalog", "context.native.preview", "comparison.preview", "comparison.get", "comparison.list", "context.catalog", "context.list", "context.get", "context.preview", "campaign.fieldwork.preview-return", "list", "get", "frontier.progress", "campaign.get", "campaign.list", "campaign.history", "capabilities", "source.catalog"}
WRITES = {"context.native.prepare", "comparison.prepare", "comparison.export", "context.prepare", "context.export", "network.import", "design", "frontier", "campaign.create", "campaign.revise", "campaign.event", "campaign.fieldwork", "campaign.fieldwork.return", "export"}

def invoke(workspace, action, params, *, export_root=None):
    if not isinstance(params, dict): raise ContractError("Monitoring parameters must be a JSON object")
    service = MonitoringWorkspace(workspace, export_root=export_root)
    if action in {"campaign.fieldwork.preview-return", "campaign.fieldwork.return"}:
        from .monitoring_field_return import preview, receive
        function = preview if action.endswith("preview-return") else receive
        try: inspect.signature(function).bind(service, **params)
        except TypeError as exc: raise ContractError(str(exc)) from exc
        return function(service, **params)
    if action == "campaign.fieldwork":
        from .monitoring_implementation import receive
        try: inspect.signature(receive).bind(service, **params)
        except TypeError as exc: raise ContractError(str(exc)) from exc
        return receive(service, **params)
    if action.startswith("comparison."):
        from . import monitoring_frontier_comparison as comparison
        functions = {"comparison.preview": comparison.preview,
                     "comparison.get": comparison.inspect,
                     "comparison.list": comparison.list_saved,
                     "comparison.prepare": comparison.prepare,
                     "comparison.export": comparison.export_comparison}
        if action not in functions:
            raise ContractError("Unknown monitoring budget comparison action")
        options = dict(params)
        if action == "comparison.export": options["export_root"] = export_root
        function = functions[action]
        try: inspect.signature(function).bind(workspace, **options)
        except TypeError as exc: raise ContractError(str(exc)) from exc
        return function(workspace, **options)
    if action.startswith("context.native."):
        from . import monitoring_native_observations as native_observations
        functions = {"context.native.catalog": native_observations.catalog,
                     "context.native.preview": native_observations.preview,
                     "context.native.prepare": native_observations.prepare}
        function = functions.get(action)
        if function is None:
            raise ContractError("Unknown native observational context action")
        try: inspect.signature(function).bind(workspace, **params)
        except TypeError as exc: raise ContractError(str(exc)) from exc
        return function(workspace, **params)
    if action.startswith("context."):
        from . import monitoring_observed_context as observed
        functions = {"context.catalog": observed.catalog, "context.list": observed.list_saved,
                     "context.get": observed.inspect, "context.preview": observed.preview,
                     "context.prepare": observed.prepare, "context.export": observed.export_context}
        if action not in functions:
            raise ContractError("Unknown monitoring context action")
        options = dict(params)
        if action == "context.export": options["export_root"] = export_root
        return functions[action](workspace, **options)
    commands = {
        "network.import": service.import_network, "list": service.list, "get": service.get,
        "design": service.design, "frontier": service.frontier, "frontier.progress": service.frontier_progress,
        "campaign.create": service.create_campaign, "campaign.get": service.campaign,
        "campaign.list": service.campaigns, "campaign.revise": service.revise_campaign,
        "campaign.event": service.field_event, "campaign.history": service.history, "export": service.export,
    }
    if action == "capabilities":
        return {"schema": "eco.monitoring.api/1.2", "commands": sorted(READS | WRITES),
                "native_write_route": "POST /api/actions", "native_read_route": "GET /api/monitoring",
                "action_prefix": "monitoring.", "geometry": "complete retained native vectors projected to WGS84",
                "source_selection": "source edition ID plus named entry ID", "default_coverage": "local",
                "editable_receiving": "original Workspace.backup and model.portable.restore"}
    if action == "source.catalog":
        if params: raise ContractError("Source catalog takes no parameters")
        if not callable(getattr(workspace, "sources", None)): return {"collections": []}
        return {"collections": [{"id": c["id"], "title": c.get("title", c["id"]), "entries": [
            {"id": e["id"], "title": e.get("title", e["id"]), "layer": e.get("layer"),
             "sha256": e["body"]["sha256"], "filename": e["body"]["filename"]}
            for e in c["entries"] if e.get("kind") == "vector"]} for c in workspace.sources()]}
    function = commands.get(action)
    if function is None: raise ContractError(f"Unknown monitoring action: {action}")
    try: inspect.signature(function).bind(**params)
    except TypeError as exc: raise ContractError(str(exc)) from exc
    return function(**params)

"""Source-bound observation gaps and editable proposed monitoring programmes.

Recommendations describe retained observations and explicit operator goals.
The existing native monitoring solver and calendar own any requested design.
"""
from __future__ import annotations
import argparse
import copy
import html
import json
import re
import uuid
from collections import Counter
from datetime import date, datetime
from decimal import Decimal, InvalidOperation
from pathlib import Path

from .monitoring_common import ContractError, canonical_bytes, digest, held, atomic_json, load_json
from . import monitoring_observed_context as observed_context
from . import monitoring_native_evidence as native_evidence

COLLECTION = "monitoring_recommendations"
DESIGNS = "monitoring_recommendation_designs"
SCHEMA = "upstate.monitoring_recommendations/v1"
COHORT_FIELDS = ("characteristic", "method", "unit", "fraction", "result_value_type", "speciation",
    "method_id", "method_context", "method_name", "method_specification", "activity_type",
    "sample_media", "sample_media_subdivision", "sample_fraction", "value_type", "weight_basis",
    "analytical_fraction", "depth_value", "depth_unit", "result_depth_value", "result_depth_unit",
    "project_id", "organization_id")
TARGET_KEYS = {"id", "station_id", "cohort_id", "months", "minimum_dates_per_month",
               "proposed_visits", "reporting_limit", "reporting_limit_basis", "flow_goal",
               "reason", "priority", "included", "setup_cost", "per_visit_cost",
               "cost_basis", "sensitivity_basis", "model_evidence"}
SELECTION_KEYS = {"context_id", "title", "operator", "recorded_at", "evidence_start",
                  "evidence_end", "notes", "planning_basis", "targets"}


def _text(value, name, *, empty=False, limit=20000):
    if not isinstance(value, str) or len(value) > limit or (not empty and not value.strip()):
        raise ContractError(name + " must be " + ("a" if empty else "a nonempty") + " text value")
    return value


def _id(value, name):
    value = _text(value, name, limit=200)
    if value != value.strip() or not re.fullmatch(r"[A-Za-z0-9_.:-]+", value):
        raise ContractError(name + " must be an exact identifier without whitespace")
    return value


def _date(value, name):
    try:
        if not isinstance(value, str) or date.fromisoformat(value).isoformat() != value:
            raise ValueError()
        return value
    except (ValueError, TypeError) as exc:
        raise ContractError(name + " must be YYYY-MM-DD") from exc


def _time(value):
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            raise ValueError()
    except (AttributeError, ValueError, TypeError) as exc:
        raise ContractError("recorded_at needs an actual ISO timestamp including timezone") from exc
    return value


def _integer(value, name, minimum=0):
    if type(value) is not int or value < minimum:
        raise ContractError(name + " must be an integer >= " + str(minimum))
    return value


def _decimal(value, name, *, money=False):
    if value is None:
        return None
    if not isinstance(value, str) or not re.fullmatch(r"(?:0|[1-9][0-9]*)(?:\.[0-9]+)?", value):
        raise ContractError(name + " must be null or an explicit nonnegative decimal string")
    try:
        d = Decimal(value)
    except InvalidOperation as exc:
        raise ContractError(name + " is not an exact decimal") from exc
    if not d.is_finite() or d < 0 or len(value) > 100:
        raise ContractError(name + " is outside its supported numeric range")
    if money:
        if d * 100 != (d * 100).to_integral_value() or d * 100 > 10**12:
            raise ContractError(name + " needs at most two decimal places and <= 10000000000")
        return format(d, ".2f")
    return value


def _cohort(row):
    keys = COHORT_FIELDS
    if row.get("sampling_cohort_schema") == "upstate.native-observation-sampling-cohort/v1":
        keys = COHORT_FIELDS + ("time_basis", "temperature_basis", "particle_size_basis",
                                "time_support", "quantity_basis", "measurement_support")
    fields = {key: {"present": key in row, "value": row.get(key)} for key in keys}
    return digest(fields), fields


def _label(fields):
    def show(key):
        field = fields[key]
        return str(field["value"]) if field["present"] and field["value"] is not None else "unspecified"
    return " · ".join(show(key) for key in ("characteristic", "method", "unit", "fraction"))


def _context_view(record):
    cohorts = {}
    for row in record.get("observations", []):
        key, fields = _cohort(row)
        item = cohorts.setdefault(key, {"id": key, "fields": fields, "label": _label(fields),
                                       "observation_count": 0, "station_ids": set()})
        item["observation_count"] += 1
        item["station_ids"].add(row["station_id"])
    values = [{**row, "station_ids": sorted(row["station_ids"])} for _, row in sorted(cohorts.items())]
    result = {"context_id": record["id"], "context_digest": digest(record),
            "network_id": record["network_id"], "network_digest": record["network_digest"],
            "source_binding": copy.deepcopy(record["source_binding"]),
            "source_period": copy.deepcopy(record["source_period"]),
            "stations": copy.deepcopy(record["station_matches"]), "cohorts": values,
            "flow_scope": copy.deepcopy(record.get("flow_scope")),
            "summary": copy.deepcopy(record["summary"])}
    if record.get("source_schema") == "upstate.monitoring-observed-source/v3":
        result["native_observation_binding"] = copy.deepcopy(record.get("native_observation_binding"))
        result["flow_availability"] = copy.deepcopy(record.get("flow_availability"))
    return result


def context(workspace, context_id):
    record = observed_context.inspect(workspace, context_id)
    result = _context_view(record)
    if record.get("plan_id"):
        from .monitoring_workspace import MonitoringWorkspace
        result["design_configuration"] = copy.deepcopy(MonitoringWorkspace(workspace).get("plans", record["plan_id"]).get("configuration"))
    else:
        result["design_configuration"] = None
    return result


def list_saved(workspace):
    records = []
    for path in sorted((workspace.root / COLLECTION).glob("*.json")):
        value = workspace._get(COLLECTION, path.stem)
        records.append({key: value.get(key) for key in ("id", "title", "context_id",
            "network_id", "parent_id", "revision", "operator", "recorded_at", "summary", "budget")})
    return {"records": records}


def catalog(workspace):
    return {"contexts": observed_context.list_saved(workspace)["records"],
            "recommendations": list_saved(workspace)["records"], "currency": "USD",
            "model_evidence": native_evidence.catalog(workspace),
            "semantics": "Historical evidence and proposed future sampling remain separate."}


def _selection(record, selection):
    if not isinstance(selection, dict) or set(selection) - SELECTION_KEYS:
        raise ContractError("Unknown or invalid recommendation selection fields")
    if selection.get("context_id") != record["id"]:
        raise ContractError("Choose the exact retained observed context")
    result = copy.deepcopy(selection)
    for key in ("title", "operator", "planning_basis"):
        _text(result.get(key), key)
    for key in ("notes",):
        result[key] = _text(result.get(key, ""), key, empty=True)
    result["recorded_at"] = _time(result.get("recorded_at"))
    start, end = _date(result.get("evidence_start"), "evidence_start"), _date(result.get("evidence_end"), "evidence_end")
    if end < start:
        raise ContractError("The selected evidence window is reversed")
    period = record["source_period"]
    if start < period["start_inclusive"] or end > period["end_inclusive"]:
        raise ContractError("The evidence window must stay inside the declared original source period")
    targets = result.get("targets")
    if not isinstance(targets, list) or not targets:
        raise ContractError("Add at least one explicit station/cohort target")
    view = _context_view(record)
    stations = {r["source_station_id"]: r for r in view["stations"]}
    cohorts = {r["id"]: r for r in view["cohorts"]}
    seen = set()
    for row in targets:
        if not isinstance(row, dict) or set(row) - TARGET_KEYS:
            raise ContractError("Unknown or invalid target fields")
        key = _id(row.get("id"), "target.id")
        if key in seen:
            raise ContractError("Target IDs must be unique")
        seen.add(key)
        if row.get("station_id") not in stations or row.get("cohort_id") not in cohorts:
            raise ContractError("Targets must use an original source station and a retained exact cohort")
        months = row.get("months")
        if not isinstance(months, list) or not months or any(type(v) is not int or not 1 <= v <= 12 for v in months) or len(set(months)) != len(months):
            raise ContractError("Target months must be distinct integers 1 through 12")
        row["months"] = sorted(months)
        for key in ("minimum_dates_per_month", "proposed_visits"):
            _integer(row.get(key), key)
        _integer(row.get("priority"), "priority", 1)
        if row["priority"] > 5 or type(row.get("included")) is not bool:
            raise ContractError("Priority must be 1 through 5 and included must be boolean")
        if row.get("flow_goal") not in {"any", "high_flow"}:
            raise ContractError("flow_goal must be any or high_flow")
        for key in ("reason",):
            _text(row.get(key), key)
        for key in ("reporting_limit_basis", "cost_basis", "sensitivity_basis"):
            row[key] = _text(row.get(key, ""), key, empty=True)
        for key in ("setup_cost", "per_visit_cost"):
            row[key] = _decimal(row.get(key), key, money=True)
        if "model_evidence" in row:
            row["model_evidence"] = native_evidence.normalize(row["model_evidence"])
        row["reporting_limit"] = _decimal(row.get("reporting_limit"), "reporting_limit")
        if row["reporting_limit"] is not None and not row["reporting_limit_basis"].strip():
            raise ContractError("A proposed reporting limit needs its explicit scientific/operator rationale")
        if any(row[k] is not None for k in ("setup_cost", "per_visit_cost")) and not row["cost_basis"].strip():
            raise ContractError("Entered planning costs need an explicit source or operator basis")
    return result


def _as_decimal(value):
    if value is None or isinstance(value, bool):
        return None
    try:
        parsed = Decimal(str(value))
        return parsed if parsed.is_finite() else None
    except InvalidOperation:
        return None


def compile_recommendations(record, selection, *, model_evidence=None):
    """Pure calculation over an already inspected retained context."""
    selection = _selection(record, selection)
    model_evidence = {} if model_evidence is None else model_evidence
    expected = {r["id"] for r in selection["targets"] if "model_evidence" in r}
    if not isinstance(model_evidence, dict) or set(model_evidence) != expected:
        raise ContractError("Resolve each explicitly selected native evidence source before compiling")
    view = _context_view(record)
    stations = {r["source_station_id"]: r for r in view["stations"]}
    cohorts = {r["id"]: r for r in view["cohorts"]}
    by_key = {}
    for row in record.get("observations", []):
        by_key.setdefault((row["station_id"], _cohort(row)[0]), []).append(row)
    rows, gaps, required, unbound, bindings = [], [], set(), [], {}
    known_total, unknown = 0, []
    start, end = selection["evidence_start"], selection["evidence_end"]
    for target in selection["targets"]:
        station, cohort = stations[target["station_id"]], cohorts[target["cohort_id"]]
        evidence = [r for r in by_key.get((target["station_id"], target["cohort_id"]), [])
                    if start <= r["date"] <= end and int(r["date"][5:7]) in target["months"]]
        month_rows = []
        for month in target["months"]:
            matched = [r for r in evidence if int(r["date"][5:7]) == month]
            dates = sorted({r["date"] for r in matched})
            item = {"target_id": target["id"], "station_id": target["station_id"],
                    "cohort_id": target["cohort_id"], "month": month,
                    "observed_dates": len(dates), "dates": dates,
                    "years_with_observations": sorted({d[:4] for d in dates}),
                    "minimum_dates": target["minimum_dates_per_month"],
                    "date_gap": max(0, target["minimum_dates_per_month"] - len(dates)),
                    "observation_ids": [r["observation_id"] for r in matched],
                    "activity_ids": sorted({r["activity_id"] for r in matched})}
            month_rows.append(item)
            gaps.append(item)
        desired = _as_decimal(target["reporting_limit"])
        unit_field = cohort["fields"]["unit"]
        unit = unit_field["value"] if unit_field["present"] else None
        limits, limit_unknown, limit_incompatible = [], [], []
        for original in evidence:
            limit = _as_decimal(original.get("limit_value"))
            if limit is None:
                limit_unknown.append(original["observation_id"])
                continue
            limit_unit = original.get("limit_unit", original.get("unit"))
            if unit is None or limit_unit != unit:
                limit_incompatible.append(original["observation_id"])
                continue
            limits.append({"observation_id": original["observation_id"],
                           "value": str(limit), "unit": limit_unit,
                           "above_target": bool(limit > desired) if desired is not None else None})
        scope = record.get("flow_scope")
        flow_eligible = bool(scope and target["station_id"] in scope["station_ids"])
        episodes = []
        if flow_eligible:
            for ep in record.get("high_flow_episodes", []):
                # An event is historical evidence only when it overlaps this
                # exact source window and one of the chosen calendar months.
                lo, hi = max(start, ep["start_date"], scope.get("start_inclusive") or start), min(end, ep["end_date"], scope.get("end_inclusive") or end)
                if lo > hi:
                    continue
                sample_dates = sorted({r["date"] for r in evidence if lo <= r["date"] <= hi
                                       and r.get("activity_type") == "Sample-Routine"})
                from datetime import timedelta
                cursor, months = date.fromisoformat(lo), set()
                final = date.fromisoformat(hi)
                while cursor <= final:
                    months.add(cursor.month)
                    cursor += timedelta(days=1)
                if not months.intersection(target["months"]):
                    continue
                episodes.append({"event_id": ep["event_id"], "start_date": ep["start_date"],
                                 "end_date": ep["end_date"], "sampled_dates": sample_dates,
                                 "has_selected_routine_observation": bool(sample_dates),
                                 "activity_type_unknown_observation_ids": [r["observation_id"] for r in evidence if lo <= r["date"] <= hi and not r.get("activity_type")]})
        setup = None if target["setup_cost"] is None else int(Decimal(target["setup_cost"]) * 100)
        visit = None if target["per_visit_cost"] is None else int(Decimal(target["per_visit_cost"]) * 100)
        total = None if setup is None or visit is None else setup + visit * target["proposed_visits"]
        if target["included"]:
            if total is None:
                unknown.append(target["id"])
            else:
                known_total += total
            catchment, native = station.get("catchment_id"), station.get("network_station_id")
            if catchment and native:
                required.add(catchment)
                bindings.setdefault(catchment, set()).add(native)
            else:
                unbound.append(target["id"])
        warnings = []
        if not station.get("network_station_id"):
            warnings.append("The original source station is not bound to the saved network.")
        if not station.get("catchment_id"):
            warnings.append("No retained source-catchment assignment is available.")
        if target["flow_goal"] == "high_flow" and not flow_eligible:
            warnings.append("The received flow series is not declared applicable to this exact station; event coverage is unknown.")
        if not evidence:
            warnings.append("No matching retained observation occurs in the selected window and months; this is source-record absence.")
        if any(not f["present"] or f["value"] is None for f in cohort["fields"].values()):
            warnings.append("Some original cohort metadata is unspecified; the exact missing/null fields remain separate.")
        if target["sensitivity_basis"].strip():
            warnings.append("Sensitivity rationale is operator-supplied context; this compiler computes no model information gain.")
        if total is None:
            warnings.append("The target's complete planning cost is unknown.")
        rows.append({"target_id": target["id"], "target": copy.deepcopy(target),
                     "station": copy.deepcopy(station), "cohort": copy.deepcopy(cohort),
                     "evidence": {"start": start, "end": end, "observations": len(evidence),
                         "distinct_dates": len({r["date"] for r in evidence}),
                         "observation_ids": [r["observation_id"] for r in evidence],
                         "activity_ids": sorted({r["activity_id"] for r in evidence}),
                         "status_counts": dict(Counter(str(r.get("status")) for r in evidence)),
                         "monthly": month_rows, "reporting_limits": limits,
                         "unknown_limit_observation_ids": limit_unknown,
                         "incompatible_limit_unit_observation_ids": limit_incompatible,
                         "flow_scope_eligible": flow_eligible, "high_flow_episodes": episodes},
                     "cost": {"currency": "USD", "setup_cents": setup,
                              "per_visit_cents": visit, "proposed_visits": target["proposed_visits"],
                              "total_cents": total, "basis": target["cost_basis"]},
                     "warnings": warnings})
        if target["id"] in model_evidence:
            resolved = model_evidence[target["id"]]
            if resolved.get("selection") != target["model_evidence"]:
                raise ContractError("The resolved native evidence differs from the target choice")
            rows[-1]["model_evidence"] = copy.deepcopy(resolved)
            warnings.append("Native evidence supports authored sampling rationale; station-catchment and quantitative constituent equivalence are not established.")
    conflicts = [{"catchment_id": k, "station_ids": sorted(v)} for k, v in sorted(bindings.items()) if len(v) > 1]
    return {"schema": SCHEMA, "title": selection["title"], "selection": selection,
            "context_id": record["id"], "context_digest": digest(record),
            "network_id": record["network_id"], "network_digest": record["network_digest"],
            "source_binding": copy.deepcopy(record["source_binding"]),
            "source_period": copy.deepcopy(record["source_period"]),
            "context_snapshot": copy.deepcopy(record), "operator": selection["operator"],
            "recorded_at": selection["recorded_at"], "targets": rows, "gaps": gaps,
            "budget": {"currency": "USD", "known_total_cents": known_total,
                       "unknown_target_ids": unknown, "complete": not unknown,
                       "basis": "Sum of included target setup plus proposed visits times entered per-visit cost; overlaps are not automatically discounted."},
            "handoff": {"required_catchment_ids": sorted(required), "unbound_target_ids": unbound,
                        "station_binding_conflicts": conflicts,
                        "station_bindings": {k: next(iter(v)) for k, v in sorted(bindings.items()) if len(v) == 1},
                        "requirements": [copy.deepcopy(r["target"]) for r in rows if r["target"]["included"]]},
            "summary": {"targets": len(rows), "included": sum(r["target"]["included"] for r in rows),
                        "month_gaps": sum(r["date_gap"] > 0 for r in gaps),
                        "missing_dates_to_operator_goal": sum(r["date_gap"] for r in gaps),
                        "unbound_targets": len(unbound)},
            "interpretation": [
                "Monthly coverage goals count distinct historical dates across the selected evidence window, not laboratory replicates or a per-year target.",
                "Proposed future visits, desired reporting limits, priorities and costs are explicit planning choices, not collected observations or guaranteed information gain.",
                "Original method, fraction, unit, value type, speciation and missing/null metadata remain separate cohorts. No unit conversion or censored-value substitution occurs.",
                "A high-flow episode describes the original gauge and period; a future calendar cannot promise a storm or substitute nearby-gauge flow.",
                "Existing network/design/calendar actions select catchment search areas. Station bindings, laboratory scope and event-triggered field work require explicit operator decisions.",
                "Included target costs are an itemized authored planning estimate. The requested native design retains its own entered budget and costs separately."
            ]}


def preview(workspace, *, selection):
    record = observed_context.inspect(workspace, selection.get("context_id") if isinstance(selection, dict) else None)
    selected = _selection(record, selection)
    return compile_recommendations(record, selected,
        model_evidence=native_evidence.resolve(workspace, record, selected))


def _operation(workspace, operation_id, request, perform):
    key = digest({"operation_id": _id(operation_id, "operation_id")})
    path = workspace.root / "monitoring_recommendation_operations" / (key + ".json")
    fingerprint = digest(request)
    with held(path.with_suffix(".lock")):
        if path.exists():
            prior = load_json(path)
            if prior["fingerprint"] != fingerprint:
                raise ContractError("This operation ID already belongs to a different request")
            return workspace._get(prior["collection"], prior["record_id"])
        # Recover death after immutable save, before the small operation index.
        for collection in (COLLECTION, DESIGNS):
            for candidate in sorted((workspace.root / collection).glob("*.json")):
                row = workspace._get(collection, candidate.stem)
                if row.get("operation_id") == operation_id:
                    if row.get("request_fingerprint") != fingerprint:
                        raise ContractError("This operation ID has a different retained immutable request")
                    atomic_json(path, {"fingerprint": fingerprint, "collection": collection, "record_id": row["id"]})
                    return row
        collection, row = perform(fingerprint)
        atomic_json(path, {"fingerprint": fingerprint, "collection": collection, "record_id": row["id"]})
        return row


def prepare(workspace, *, selection, operation_id, parent_id=None, expected_parent_digest=None):
    request = copy.deepcopy({"kind": "prepare", "selection": selection, "parent_id": parent_id,
                             "expected_parent_digest": expected_parent_digest})
    selection = request["selection"]
    def perform(fingerprint):
        parent = inspect(workspace, parent_id) if parent_id else None
        if parent is None and expected_parent_digest is not None:
            raise ContractError("A parent digest requires the exact parent proposal")
        if parent is not None:
            if parent["id"] != expected_parent_digest:
                raise ContractError("The selected parent proposal differs; reopen its exact immutable edition")
            if parent["context_id"] != selection.get("context_id"):
                raise ContractError("Changing the source context starts a new proposal family")
        value = preview(workspace, selection=selection)
        value.update(parent_id=parent_id, revision=parent["revision"] + 1 if parent else 1,
                     operation_id=operation_id, request_fingerprint=fingerprint,
                     request_payload=copy.deepcopy(request))
        return COLLECTION, workspace._save(COLLECTION, value)
    return _operation(workspace, operation_id, request, perform)


def inspect(workspace, recommendation_id):
    value = workspace._get(COLLECTION, recommendation_id)
    if value.get("schema") != SCHEMA:
        raise ContractError("Unsupported saved recommendation schema")
    context_value = observed_context.inspect(workspace, value["context_id"])
    if digest(context_value) != value["context_digest"] or context_value != value["context_snapshot"]:
        raise ContractError("The saved recommendation differs from its retained original observed context")
    # Native IDs validate payload bytes; ancestry validates the actual family.
    seen, current = set(), value
    while current:
        if current["id"] in seen:
            raise ContractError("Recommendation ancestry contains a cycle")
        seen.add(current["id"])
        _integer(current.get("revision"), "proposal revision", 1)
        _id(current.get("operation_id"), "operation_id")
        parent_id = current.get("parent_id")
        expected = current.get("request_payload")
        if (not isinstance(expected, dict) or set(expected) != {"kind", "selection", "parent_id", "expected_parent_digest"}
                or expected["kind"] != "prepare" or expected["parent_id"] != parent_id
                or expected["expected_parent_digest"] != parent_id
                or _selection(context_value, expected["selection"]) != current["selection"]
                or current.get("request_fingerprint") != digest(expected)):
            raise ContractError("Proposal request identity differs from its complete saved selection")
        if parent_id is None:
            if current["revision"] != 1:
                raise ContractError("A proposal without a parent must be revision 1")
            break
        parent = workspace._get(COLLECTION, parent_id)
        if (parent.get("schema") != SCHEMA or parent.get("context_id") != value["context_id"]
                or current["revision"] != parent.get("revision", 0) + 1):
            raise ContractError("Proposal ancestry differs in source context or revision sequence")
        current = parent
    recomputed = compile_recommendations(context_value, value["selection"],
        model_evidence=native_evidence.resolve(workspace, context_value, value["selection"]))
    for key in recomputed:
        if key != "schema" and value.get(key) != recomputed[key]:
            raise ContractError("The saved recommendation no longer matches its exact calculation: " + key)
    return value


def history(workspace, recommendation_id):
    result, seen = [], set()
    current = inspect(workspace, recommendation_id)
    while current:
        if current["id"] in seen:
            raise ContractError("Recommendation ancestry contains a cycle")
        seen.add(current["id"])
        result.append(current)
        current = inspect(workspace, current["parent_id"]) if current.get("parent_id") else None
    return list(reversed(result))


def inspect_design(workspace, design_id):
    from .monitoring_workspace import MonitoringWorkspace
    value = workspace._get(DESIGNS, design_id)
    if value.get("schema") != "upstate.monitoring_recommendation_designs/v1":
        raise ContractError("Unsupported saved recommendation design schema")
    proposal = inspect(workspace, value["recommendation_id"])
    request = value.get("request_payload")
    if (not isinstance(request, dict) or set(request) != {"kind", "recommendation_id", "configuration", "title"}
            or request["kind"] != "design" or request["recommendation_id"] != proposal["id"]
            or request["configuration"] != value["configuration"]
            or digest(request) != value.get("request_fingerprint")):
        raise ContractError("Retained design request differs from its complete original payload")
    service = MonitoringWorkspace(workspace)
    plan = service.get("plans", value["plan_id"])
    network = service.get("networks", proposal["network_id"])
    service.verify_sources(network)
    if (digest(proposal) != value["recommendation_digest"] or digest(plan) != value["plan_digest"]
            or digest(network) != proposal["network_digest"]
            or value.get("context_id") != proposal["context_id"]
            or value.get("network_id") != proposal["network_id"]
            or plan.get("network_id") != proposal["network_id"]
            or plan.get("configuration") != value.get("configuration")
            or plan.get("title") != (request["title"] or proposal["title"] + " — native design")
            or plan.get("recommendation_id") != proposal["id"]
            or plan.get("recommendation_operation_id") != value.get("operation_id")
            or plan.get("recommendation_request_fingerprint") != value.get("request_fingerprint")
            or value.get("target_calendar") != _target_calendar(proposal, plan)
            or value.get("status") != plan.get("status")
            or value.get("native_cost") != plan.get("cost")
            or value.get("proposal_budget") != proposal["budget"]
            or value.get("station_bindings") != proposal["handoff"]["station_bindings"]):
        raise ContractError("Saved native design differs from its proposal, network, configuration or exact calendar")
    return value


def designs(workspace, recommendation_id):
    inspect(workspace, recommendation_id)
    result = []
    for path in sorted((workspace.root / DESIGNS).glob("*.json")):
        value = workspace._get(DESIGNS, path.stem)
        if value.get("recommendation_id") == recommendation_id:
            result.append(inspect_design(workspace, path.stem))
    return result


def _target_calendar(proposal, plan):
    visits = plan.get("calendar", {}).get("visits", [])
    outcomes = []
    for target in proposal["handoff"]["requirements"]:
        station = next(r["station"] for r in proposal["targets"] if r["target_id"] == target["id"])
        matched = [v for v in visits if v["site_id"] == station["catchment_id"]
                   and int(v["date"][5:7]) in target["months"]]
        outcomes.append({"target_id": target["id"], "catchment_id": station["catchment_id"],
                         "station_id": target["station_id"],
                         "native_station_id": station["network_station_id"],
                         "proposed_visits": target["proposed_visits"],
                         "calendar_visits_in_selected_months": len(matched),
                         "visit_keys": [v["visit_key"] for v in matched],
                         "calendar_count_meets_request": len(matched) >= target["proposed_visits"],
                         "flow_goal": target["flow_goal"],
                         "field_scope": "Proposed source-station binding and laboratory scope; no collected event is created."})
    return outcomes


def design(workspace, *, recommendation_id, configuration, operation_id, title=None):
    """Invoke the maintained solver once, preserving planning/source distinctions."""
    request = copy.deepcopy({"kind": "design", "recommendation_id": recommendation_id,
                             "configuration": configuration, "title": title})
    configuration = request["configuration"]
    def perform(fingerprint):
        from .monitoring_workspace import MonitoringWorkspace
        from .monitoring_design import solve_design
        from .monitoring_campaign import rounds
        proposal = inspect(workspace, recommendation_id)
        if not isinstance(configuration, dict):
            raise ContractError("Supply the complete explicit native design configuration")
        if not proposal["summary"]["included"]:
            raise ContractError("Include at least one sampling target before preparing a native design")
        if proposal["handoff"]["unbound_target_ids"]:
            raise ContractError("Bind target source stations to the retained network before a native design")
        if proposal["handoff"]["station_binding_conflicts"]:
            raise ContractError("This native campaign binds one station per catchment; split or reconcile the conflicting targets")
        config = copy.deepcopy(configuration)
        required = set(proposal["handoff"]["required_catchment_ids"])
        if not required.issubset(set(config.get("required_ids", []))):
            raise ContractError("Explicit native required_ids must include every selected target's catchment")
        calendar = config.get("calendar")
        if not isinstance(calendar, dict):
            raise ContractError("Supply the full native calendar")
        if _date(calendar.get("start_date"), "calendar.start_date") <= proposal["selection"]["evidence_end"]:
            raise ContractError("A proposed future campaign must begin after the selected historical evidence window")
        rounds(calendar)  # Original calendar owns its complete validation.
        service = MonitoringWorkspace(workspace)
        network = service.get("networks", proposal["network_id"])
        service.verify_sources(network)
        if digest(network) != proposal["network_digest"]:
            raise ContractError("Native design network differs from the source-bound proposal")
        # A crashed call after plan save is recovered through its original marker.
        plan = None
        for path in sorted((workspace.root / "monitoring_plans").glob("*.json")):
            candidate = service.get("plans", path.stem)
            if candidate.get("recommendation_operation_id") == operation_id:
                if candidate.get("recommendation_request_fingerprint") != fingerprint:
                    raise ContractError("Retained solver plan has a different exact request")
                plan = candidate
                break
        if plan is None:
            calculated = solve_design(network, config)
            calculated.update(title=title or proposal["title"] + " — native design",
                              recommendation_id=recommendation_id,
                              recommendation_operation_id=operation_id,
                              recommendation_request_fingerprint=fingerprint)
            plan = service.save("plans", calculated)
        outcomes = _target_calendar(proposal, plan)
        value = {"recommendation_id": recommendation_id, "recommendation_digest": digest(proposal),
                 "network_id": proposal["network_id"], "context_id": proposal["context_id"],
                 "plan_id": plan["id"], "plan_digest": digest(plan), "configuration": config,
                 "operation_id": operation_id, "request_fingerprint": fingerprint,
                 "request_payload": copy.deepcopy(request), "status": plan["status"], "target_calendar": outcomes,
                 "station_bindings": proposal["handoff"]["station_bindings"],
                 "native_cost": plan.get("cost"), "proposal_budget": proposal["budget"],
                 "interpretation": "The unchanged native solver enforces its geographic/calendar/budget constraints. Analyte, reporting-limit and high-flow goals remain explicit field/laboratory requirements."}
        return DESIGNS, workspace._save(DESIGNS, value)
    return _operation(workspace, operation_id, request, perform)


def report_html(record, native_designs=None):
    esc = lambda v: html.escape("" if v is None else str(v))
    def table(headers, rows):
        return "<div class='table'><table><thead><tr>" + "".join("<th>" + esc(x) + "</th>" for x in headers) + "</tr></thead><tbody>" + "".join("<tr>" + "".join("<td>" + esc(x) + "</td>" for x in row) + "</tr>" for row in rows) + "</tbody></table></div>"
    def money(cents):
        return "Unknown" if cents is None else "USD " + format(Decimal(cents) / 100, ".2f")
    targets = table(["Target / source station", "Retained analytical cohort", "Months", "Historic dates / goal", "Proposed visits", "Planning cost", "Rationale"], [
        (r["target_id"] + " / " + r["target"]["station_id"], r["cohort"]["label"],
         ", ".join(str(m) for m in r["target"]["months"]),
         "; ".join(str(m["month"]) + ": " + str(m["observed_dates"]) + " / " + str(m["minimum_dates"]) for m in r["evidence"]["monthly"]),
         r["target"]["proposed_visits"], money(r["cost"]["total_cents"]),
         r["target"]["reason"] + (" [Excluded from proposal]" if not r["target"]["included"] else ""))
        for r in record["targets"]])
    details = ""
    for row in record["targets"]:
        target = row["target"]
        details += "<section><h2>" + esc(target["id"]) + ": " + esc(row["cohort"]["label"]) + "</h2>"
        details += "<p>Reporting-limit target: " + esc(target["reporting_limit"] if target["reporting_limit"] is not None else "Not entered") + ". " + esc(target["reporting_limit_basis"]) + "</p>"
        details += "<p>Cost basis: " + esc(target["cost_basis"] or "Not entered") + ". Sensitivity context: " + esc(target["sensitivity_basis"] or "No model-sensitivity basis selected") + ".</p>"
        if "model_evidence" in row:
            from .monitoring_evidence_report import render
            details += render(row["model_evidence"])
        if row["evidence"]["flow_scope_eligible"]:
            details += "<p>Flow goal: " + esc(target["flow_goal"]) + "; matching historical episodes: " + str(len(row["evidence"]["high_flow_episodes"])) + ". The retained flow scope applies to this station.</p>"
        else:
            details += "<p>Flow goal: " + esc(target["flow_goal"]) + ". Historical event coverage is unavailable for this station and source scope.</p>"
        details += "<ul>" + "".join("<li>" + esc(x) + "</li>" for x in row["warnings"]) + "</ul>"
        details += "<details><summary>Exact supporting observation and activity identifiers</summary><pre>" + esc(json.dumps({"observations": row["evidence"]["observation_ids"], "activities": row["evidence"]["activity_ids"], "cohort": row["cohort"]["fields"]}, ensure_ascii=False, indent=2)) + "</pre></details></section>"
    native = ""
    for item in native_designs or []:
        native += "<h2>Saved native design " + esc(item["plan_id"]) + "</h2><p>Status: " + esc(item["status"]) + ".</p>"
        native += table(["Target", "Proposed visits", "Native calendar visits in selected months", "Count met"], [
            (r["target_id"], r["proposed_visits"], r["calendar_visits_in_selected_months"], r["calendar_count_meets_request"]) for r in item["target_calendar"]])
    total = money(record["budget"]["known_total_cents"])
    source_support = ""
    if record["context_snapshot"].get("source_schema") == "upstate.monitoring-observed-source/v3":
        from .monitoring_concentration_report import sampling_support
        source_support = sampling_support(record["context_snapshot"])
    return ("<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
