import {attachMonitoringFieldSelection} from './monitoring-field-selection.mjs';
import {attachMonitoringFrontiers} from './monitoring-frontiers.mjs';
import {attachMonitoringFieldReturn} from './monitoring_field_return.mjs';
import {attachMonitoringFieldwork} from './monitoring_fieldwork.mjs';
import {attachMonitoringReport} from './monitoring-report.mjs';
import {attachMonitoringStudyTransfer} from './monitoring-study-transfer.mjs';
/* Native host adapter: original authorization, task queue and file tickets. */
const READS = new Set(['comparison.preview','comparison.get','comparison.list','campaign.fieldwork.preview-return','context.catalog','context.list','context.get','context.preview','list','get','frontier.progress','campaign.get','campaign.list','campaign.history','capabilities','source.catalog']);
let componentReady;
function component() {
  // The component is derived from the same shipped legacy entry, with external
  // CSS. No inline-script/style exemptions are added to the operator CSP.
  globalThis.__ecoMonitoringNativeHost = true;
  return componentReady ||= import('./monitoring-component.mjs');
}
const wait = ms => new Promise(resolve => setTimeout(resolve, ms));

export function attachMonitoring(host) {
  const {getState, api, endpoint, showTask, toast}=host;
  const fieldwork=attachMonitoringFieldwork({...host,transport});
  const fieldReturn=attachMonitoringFieldReturn({...host,transport});
  const nodes = new Map(), pendingMemory = new Map();
  const storage = {
    get(key) {
      try { return sessionStorage.getItem(key); }
      catch { return pendingMemory.get(key) || null; }
    },
    set(key, value) {
      pendingMemory.set(key, value);
      try { sessionStorage.setItem(key, value); } catch {}
    },
    remove(key) {
      pendingMemory.delete(key);
      try { sessionStorage.removeItem(key); } catch {}
    }
  };
  let active = null, generation = 0, updating = false, networkOpening = 0;
  const completedByWorkspace = new Map();
  function workspace() {const key = getState()?.workspace_key;if(!key)throw Error('Select an original workspace.');return key;}
  async function transport(key, action, payload={}) {
    if(READS.has(action))return api('/api/monitoring?'+new URLSearchParams({workspace:key,action,payload:JSON.stringify(payload)}));
    const request={workspace:key,action:'monitoring.'+action,payload:{...payload}};
    // A failed HTTP exchange must retry the original campaign mutation, not the
    // new UUID generated by the form's next click with otherwise identical input.
    const campaignMutation=action.startsWith('campaign.');
    if(campaignMutation)delete request.payload.operation_id;
    const raw=new TextEncoder().encode(JSON.stringify(request));
    const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',raw))].map(x=>x.toString(16).padStart(2,'0')).join('');
    const storedKey='eco-monitoring-request:'+key+':'+hash;
    let pending;
    try {pending=JSON.parse(storage.get(storedKey)||'null');} catch {pending=null;}
    if(!pending){pending={operation_id:crypto.randomUUID()};storage.set(storedKey,JSON.stringify(pending));}
    if(campaignMutation)request.payload.operation_id=pending.operation_id;
    let task=await api('/api/actions',{method:'POST',body:{...request,operation_id:pending.operation_id}});
    pending.task_id=task.id;storage.set(storedKey,JSON.stringify(pending));
    while(['queued','running'].includes(task.state)){
      await wait(600);
      task=await api('/api/task?'+new URLSearchParams({workspace:key,id:task.id}));
    }
    if(task.state!=='complete'){
      showTask?.(task.id);
      throw Error((task.error?.message||`The retained task is ${task.state}.`)+ ' Open its existing task to resume.');
    }
    // Refresh through the original task decorator for authenticated file links.
    task=await api('/api/task?'+new URLSearchParams({workspace:key,id:task.id}));
    storage.remove(storedKey);
    return task.result;
  }
  async function openNetwork(selection) {
    const key=workspace(), id=typeof selection==='string'?selection:selection?.network_id;
    if(!/^[0-9a-f]{64}$/.test(id||''))throw Error('Choose a retained monitoring network.');
    if(selection?.workspace_key && selection.workspace_key!==key)throw Error('Open this network in its original workspace.');
    const ticket=++networkOpening;
    await component();
    const network=await transport(key,'get',{kind:'networks',record_id:id});
    if(ticket!==networkOpening || workspace()!==key)throw Error('The workspace or network selection changed. Open the selected network again.');
    if(network.id!==id)throw Error('The retained monitoring network identity changed.');
    let node=nodes.get(key);
    if(!node){node=document.createElement('eco-monitoring');node.transport=(action,payload)=>transport(key,action,payload);nodes.set(key,node);}
    if(node.busy)throw Error('Finish the current monitoring operation before opening another network.');
    applyNetwork(node,network);
    return {network_id:id,workspace_key:key};
  }
  function applyNetwork(node,network) {
    const scoped=Object.values(network.nodes||{}).filter(row=>typeof row.source_properties?.rwmon_in_scope==='boolean');
    let scopedConfiguration=null;
    if(node.network?.id!==network.id && scoped.length){
      scopedConfiguration={...node.json('advanced')};
      for(const field of ['required_ids','existing_station_ids','minimum_by_stratum','site_costs','incompatible_pairs'])delete scopedConfiguration[field];
      scopedConfiguration.excluded_ids=scoped.filter(row=>!row.source_properties.rwmon_in_scope).map(row=>row.id).sort();
      scopedConfiguration.required_ids=[];scopedConfiguration.existing_station_ids=[];scopedConfiguration.minimum_by_stratum={};
    }
    node.network=network;node.plan=null;node.campaign=null;
    if(scopedConfiguration)node.$('advanced').value=JSON.stringify(scopedConfiguration,null,2);
    const select=node.$('networks');
    if(![...select.options].some(option=>option.value===network.id))select.add(new Option(network.title||network.id,network.id));
    select.value=network.id;node.$('plans').value='';node.$('campaigns').value='';
    node.$('frontier-results').replaceChildren();node.$('downloads').replaceChildren();
    node.render();
    if(scoped.length){node.$('status').textContent='Opened the original network. Candidate search starts inside the selected water scope; the complete HUC routing remains available. Review Advanced constraints, costs and calendar before solving.';node.$('status').dataset.error='false';}
  }
  function selectRecord(node,name,record,label) {
    const select=node.$(name);
    if (!record) {select.value='';return;}
    if (![...select.options].some(option=>option.value===record.id))
      select.add(new Option(label||record.title||record.id,record.id));
    select.value=record.id;
  }
  async function openStudy(selection) {
    const key=workspace(),kind=selection?.kind,id=selection?.id;
    const kinds=new Set(['monitoring_networks','monitoring_plans','monitoring_heads','monitoring_observed_contexts']);
    if (!kinds.has(kind)||!/^[0-9a-f]{64}$/.test(id||''))
      throw Error('Choose an original saved Monitoring network, design, campaign or context.');
    if (selection.workspace_key!==key) throw Error('Open this Monitoring study in its original workspace.');
    const node=active;
    if (!node?.isConnected||nodes.get(key)!==node)
      throw Error('Open Monitoring in this workspace before selecting its saved study.');
    if (node.busy) throw Error('Finish the current Monitoring operation before opening this study.');
    const ticket=++networkOpening,version=generation;
    const current=()=>ticket===networkOpening&&version===generation&&active===node&&node.isConnected&&workspace()===key;
    let result,failure;
    await node.run(async()=>{
      try {
        let network,plan=null,campaign=null,context=null;
        if (kind==='monitoring_networks') {
          network=await transport(key,'get',{kind:'networks',record_id:id});
          if (network.id!==id) throw Error('The saved Monitoring network identity changed.');
        } else if (kind==='monitoring_plans') {
          plan=await transport(key,'get',{kind:'plans',record_id:id});
          if (plan.id!==id) throw Error('The saved Monitoring design identity changed.');
          network=await transport(key,'get',{kind:'networks',record_id:plan.network_id});
          if (network.id!==plan.network_id) throw Error('The saved design points to another network.');
        } else if (kind==='monitoring_heads') {
          campaign=await transport(key,'campaign.get',{campaign_id:id});
          if (campaign.revision?.campaign_id!==id) throw Error('The saved Monitoring campaign identity changed.');
          plan=campaign.plan;
          network=await transport(key,'get',{kind:'networks',record_id:plan.network_id});
          if (network.id!==plan.network_id||campaign.revision.plan_id!==plan.id)
            throw Error('The saved campaign points to another design or network.');
        } else {
          context=await transport(key,'context.get',{context_id:id});
          if (context.id!==id) throw Error('The saved observational context identity changed.');
          network=await transport(key,'get',{kind:'networks',record_id:context.network_id});
          if (network.id!==context.network_id) throw Error('The saved context points to another network.');
          // Open the immutable context itself; its historical calendar stays in
          // the context, without substituting the campaign's newer revision.
          await node.refreshSources();
        }
        if (!current()) throw Error('The workspace or Monitoring selection changed while opening this study.');
        applyNetwork(node,network);
        if (plan) {
          node.plan=plan;node.campaign=campaign;
          node.loadConfig(plan.configuration);
          node.$('title').value=campaign?.revision?.title||plan.title;
          selectRecord(node,'plans',plan);
          selectRecord(node,'campaigns',campaign?{id:campaign.revision.campaign_id,title:campaign.revision.title}:null,
            campaign?campaign.revision.title+' · revision '+campaign.revision.revision:null);
          node.render();
        }
        if (context) node.openSavedObservedContextRecord(context);
        result={workspace_key:key,kind,id,network_id:network.id,
          plan_id:plan?.id||null,campaign_id:campaign?.revision?.campaign_id||null,
          context_id:context?.id||null};
      } catch (error) {failure=error;throw error;}
    },'Opening the original saved Monitoring study…');
    if (failure) throw failure;
    return result;
  }
  async function mount(root) {
    const key=workspace(), ticket=++generation;
    await component();
    if(ticket!==generation || workspace()!==key)return;
    let node=nodes.get(key);
    if(!node){node=document.createElement('eco-monitoring');node.transport=(action,payload)=>transport(key,action,payload);nodes.set(key,node);}
    if(active===node && node.parentNode===root)return;
    active=node;root.replaceChildren(node);
    await node.ready;
    if(ticket!==generation || workspace()!==key)return;
    node.monitoringFrontiers ||= attachMonitoringFrontiers(node,host,key);
    await node.monitoringFrontiers.mount();
    if(ticket!==generation || workspace()!==key)return;
    node.monitoringReport ||= attachMonitoringReport(node,host,key);
    node.monitoringReport.update();
    node.monitoringStudyTransfer ||= attachMonitoringStudyTransfer(node,host,key);
    node.monitoringStudyTransfer.update();
    node.monitoringFieldSelection ||= attachMonitoringFieldSelection(node,{...host,transport},key);
    await node.monitoringFieldSelection.mount();
    if(ticket!==generation || workspace()!==key)return;
    await fieldwork.mount(root,key);
    if(ticket===generation && workspace()===key)await fieldReturn.mount(root,key);
  }
  async function update() {
    active?.monitoringReport?.update();
    active?.monitoringStudyTransfer?.update();
    if (!active?.isConnected || active.busy || updating) return;
    const node = active, key = workspace(), version = generation;
    const current = () => active === node && generation === version &&
      node.isConnected && workspace() === key;
    const completed = JSON.stringify((getState()?.tasks || []).filter(task =>
      task.state === 'complete' && (task.action?.startsWith('monitoring.') || task.action?.startsWith('source.') || task.action==='receiving.water.monitoring')
    ).map(task => task.id).sort());
    if (completed === completedByWorkspace.get(key)) return;
    updating = true;
    try {
      await node.refresh();
      if (!current()) return;
      await node.refreshSources();
      if (!current()) return;
      await node.monitoringFrontiers?.update();
      if (!current()) return;
      await fieldwork.update();
      if (current()) await fieldReturn.update();
      if (current()) completedByWorkspace.set(key, completed);
    } finally { updating = false; }
  }
  function detach(){generation++;networkOpening++;active?.monitoringFrontiers?.detach();active?.monitoringReport?.detach();active?.monitoringStudyTransfer?.detach();active?.monitoringFieldSelection?.detach();fieldwork.detach();fieldReturn.detach();if(active)active.remove();active=null;}
  return {mount,update,detach,openNetwork,openStudy,render:()=>'',dispatch:()=>false};
}

